comms.text:
@1 וַהֲוָה כַּד שַׁלַח פַּרְעֹה יָת עַמָא וְלָא דַבָּרִינוּן יְיָ אֹרַח אַרְעָא פְלִשְׁתָּאֵי אֲרֵי קָרִיבָא הוּא אֲרֵי אֲמַר יְיָ דִילְמָא יְזוּעוּן עַמָא בְּמֶחֱזֵיהוֹן קְרָבָא וִיתוּבוּן לְמִצְרָיִם:
@2 וְאַסְחַר יְיָ יָת עַמָא אֹרַח מַדְבְּרָא יַמָא דְסוּף וּמְזָרְזִין סְלִיקוּ בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרָיִם:
@3 וְאַסִיק משֶׁה יָת גַרְמֵי יוֹסֵף עִמֵהּ אֲרֵי אוֹמָאָה אוֹמִי יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַרְמַי מִכָּא עִמְכוֹן:
@4 וּנְטָלוּ מִסֻכּוֹת וּשְׁרוֹ בְאֵתָם בִּסְטַר מַדְבְּרָא:
@5 וַיְיָ מְדַבַּר קָדָמֵיהוֹן בִּימָמָא בְּעַמוּדָא דַעֲנָנָא לְדַבָּרוּתְהוֹן בְּאוֹרְחָא וְלֵילְיָא בְּעַמוּדָא דְאֶשָׁתָא לְאַנְהָרָא לְהוֹן לְמֵיזַל בִּימָמָא וּבְלֵילְיָא:
@6 לָא יַעֲדֵי עַמוּדָא דַעֲנָנָא בִּימָמָא וְאַף לָא עַמוּדָא דְאֶשָׁתָא בְּלֵילְיָא קֳדָם עַמָא:
@7 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@8 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וִיתוּבּוּן וְיִשְׁרוּן קֳדָם פּוּם חִירָתָא בֵּין מִגְדוֹל וּבֵין יַמָא קֳדָם בְּעֵיל צְפוֹן לְקִבְלֵהּ תִּשְׁרוּן עַל יַמָא:
@9 וְיֵימַר פַּרְעֹה עַל בְּנֵי יִשְׂרָאֵל מְעַרְבְּלִין אִנוּן בְּאַרְעָא אֲחַד עֲלֵיהוֹן מַדְבְּרָא:
@10 וְאַתְקֵף יָת לִבָּא דְפַרְעֹה וְיִרְדַף בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ וְיִדְעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ וַעֲבָדוּ כֵן:
@11 וְאִתְחַוָא לְמַלְכָּא דְמִצְרַיִם אֲרֵי אֲזַל עַמָא וְאִתְהֲפִיךְ לִבָּא דְפַרְעֹה וְעַבְדוֹהִי לְעַמָא וַאֲמָרוּ מָא דָא עֲבַדְנָא אֲרֵי שַׁלַחְנָא יָת יִשְׂרָאֵל מִפָּלְחָנָנָא:
@12 וְטַקִיס יָת רְתִכֵּהּ וְיָת עַמֵהּ דַבַּר עִמֵהּ:
@13 וּדְבַר שִׁתְּ מְאָה רְתִכִּין בְּחִירָן וְכֹל רְתִכֵּי מִצְרָאֵי וְגִבָּרִין מְמַנָן עַל כֻּלְהוֹן:
@14 וְתַקִיף יְיָ יָת לִבָּא דְפַרְעֹה מַלְכָּא דְמִצְרַיִם וּרְדַף בָּתַר בְּנֵי יִשְׂרָאֵל וּבְנֵי יִשְׂרָאֵל נְפָקוּ בְּרֵישׁ גְלִי:
@15 וּרְדָפוּ מִצְרָאֵי בַּתְרֵיהוֹן וְאַדְבִּיקוּ יָתְהוֹן כַּד שָׁרָן עַל יַמָא כָּל סוּסָוַת רְתִכֵּי פַרְעֹה וּפָרָשׁוֹהִי וּמַשִׁרְיָתֵהּ עַל פּוּם חִירָתָא קֳדָם בְּעֵיל צְפוֹן:
@16 וּפַרְעֹה קְרֵיב וּזְקָפוּ בְנֵי יִשְׂרָאֵל יָת עֵינֵיהוֹן וְהָא מִצְרָאֵי נַטְלִין בַּתְרֵיהוֹן וּדְחִילוּ לַחֲדָא וּזְעִיקוּ בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@17 וַאֲמָרוּ לְמשֶׁה הֲמִדְלֵית קְבָרִין בְּמִצְרַיִם דְבַרְתָּנָא לִמְמַת בְּמַדְבְּרָא מָא דָא עֲבַדְתָּא לָנָא לְאַפָּקוּתָנָא מִמִצְרָיִם:
@18 הֲלָא דֵין פִּתְגָמָא דִי מַלֵלְנָא עִמָךְ בְמִצְרַיִם לְמֵימַר שְׁבוֹק מִנָנָא וְנִפְלַח יָת מִצְרָאֵי אֲרֵי טַב לָנָא דְנִפְלַח יָת מִצְרָאֵי מִדִנְמוּת בְּמַדְבְּרָא:
@19 וַאֲמַר משֶׁה לְעַמָא לָא תִדְחֲלוּן אִתְעַתָּדוּ וַחֲזוֹ יָת פּוּרְקָנָא דַיְיָ דְיַעְבֵּד לְכוֹן יוֹמָא דֵין אֲרֵי כְּמָא דִחֲזֵיתוּן יַת מִצְרָאֵי יוֹמָא דֵין לָא תוֹסְפוּן לְמֶחֱזֵיהוֹן עוֹד עַד עָלְמָא:
@20 יְיָ יְגִיחַ לְכוֹן קְרָב וְאַתּוּן תִּשְׁתְּקוּן:
@21 וַאֲמַר יְיָ לְמשֶׁה קַבֵּלִית צְלוֹתָךְ מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְיִטְלוּן:
@22 וְאַתְּ טוֹל יָת חֻטְרָךְ וַאֲרֵים יָת יְדָךְ עַל יַמָא וּבְזָעוֹהִי וְיֵעֲלוּן בְּנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא:
@23 וַאֲנָא הָא אֲנָא מְתַקֵף יָת לִבָּא דְמִצְרָאֵי וְיֵעֲלוּן בַּתְרֵיהוֹן וְאֶתְיַקַר בְּפַרְעֹה וּבְכָל מַשִׁרְיָתֵהּ בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@24 וְיִדְּעוּן מִצְרָאֵי אֲרֵי אֲנָא יְיָ בְּאִתְיַקָרוּתִי בְּפַרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי:
@25 וּנְטַל מַלְאֲכָא דַיְיָ דִמְדַבַּר קֳדָם מַשְׁרִיתָא דְיִשְׂרָאֵל וַאֲתָא מִבַּתְרֵיהוֹן וּנְטַל עַמּוּדָא דַעֲנָנָא מִן קֳדָמֵיהוֹן וּשְׁרָא מִבַּתְרֵיהוֹן:
@26 וְעַל בֵּין מַשְׁרִיתָא דְמִצְרָאֵי וּבֵין מַשְׁרִיתָא דְיִשְׂרָאֵל וַהֲוָה עֲנָנָא וְקַבְלָא לְמִצְרָאֵי וּלְיִשְׂרָאֵל נְהַר כָּל לֵילְיָא וְלָא אִתְקְרִיבוּ דֵין לְוָת דֵין כָּל לֵילְיָא:
@27 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָּא וְדַבַּר יְיָ יָת יַמָּא בְּרוּחַ קִדוּמָא תַקִיף כָּל לֵילְיָא וְשַׁוִי יָת יַמָּא לְיַבֶּשְׁתָּא וְאִתְבְּזָעוּ מַיָּא:
@28 וְעַלוּ בְנֵי יִשְׂרָאֵל בְּגוֹ יַמָא בְּיַבֶּשְׁתָּא וּמַיָּא לְהוֹן שׁוּרִין מִיַּמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@29 וּרְדָפוּ מִצְרָאֵי וְעַלוּ בַתְרֵיהוֹן כֹּל סוּסָוַת פַּרְעֹה רְתִכּוֹהִי וּפָרָשׁוֹהִי לְגוֹ יַמָא:
@30 וַהֲוָה בְּמַטְרַת צַפְרָא וְאִסְתְּכֵי יְיָ לְמַשְׁרִיתָא דְמִצְרָאֵי בְּעַמוּדָא דְאֶשָׁתָא וַעֲנָנָא וְשַׁגִישׁ יָת מַשְׁרִיתָא דְמִצְרָאֵי:
@31 וְאַעְדִי יָת גַלְגַלֵי רְתִכּוֹהִי וּמְדַבְּרִין לְהוֹן בִּתְקוֹף וַאֲמַר מִצְרָאֵי נֵעִירוֹק מִן קֳדָם יִשְׂרָאֵל אֲרֵי דָא הִיא גְבֻרְתָּא דַיְיָ דַעֲבֵד לְהוֹן קְרָבִין בְּמִצְרָיִם:
@32 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יָת יְדָךְ עַל יַמָא וִיתוּבוּן מַיָא עַל מִצְרָאֵי עַל רְתִכֵּיהוֹן וְעַל פָּרָשֵׁיהוֹן:
@33 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל יַמָא וְתָב יַמָא לְעִדַן צַפְרָא לְתָקְפֵּהּ וּמִצְרָאֵי עָרְקִין לְקַדָמוּתֵהּ וְשַׁנִיק יְיָ יָת מִצְרָאֵי בְּגוֹ יַמָא:
@34 וְתָבוּ מַיָא וַחֲפוֹ יָת רְתִכַּיָא וְיָת פָּרָשַׁיָא לְכֹל מַשִׁרְיַת פַּרְעֹה דְעַלוּ בַתְרֵיהוֹן בְּיַמָא לָא אִשְׁתָּאַר בְּהוֹן עַד חָד:
@35 וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא וּמַיָא לְהוֹן שׁוּרִין מִיַמִינֵהוֹן וּמִסְמָאלֵהוֹן:
@36 וּפְרַק יְיָ בְּיוֹמָא הַהוּא יָת יִשְׂרָאֵל מִידָא דְמִצְרָאֵי וַחֲזוֹ יִשְׂרָאֵל יָת מִצְרָאֵי מַיְתִין עַל כֵּיף יַמָא:
@37 וַחֲזָא יִשְׂרָאֵל יָת גְבוּרְתָּא יְדָא רַבְּתָא דִי עֲבַד יְיָ בְּמִצְרַיִם וּדְחִילוּ עַמָא מִן קֳדָם יְיָ וְהֵמִינוּ בְּמֵימְרָא דַיְיָ וּבִנְבִיאוּת משֶׁה עַבְדֵהּ:
@38 בְּכֵן שַׁבַּח משֶׁה וּבְנֵי יִשְׂרָאֵל יָת תִּשְׁבַּחְתָּא הָדָא קֳדָם יְיָ וַאֲמָרוּ לְמֵימָר נְשַׁבַּח וְנוֹדֶה קָדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@39 תָּקְפִּי וְתִשְׁבַּחְתִּי דְחִילָא יְיָ וַאֲמַר בְּמֵימְרֵהּ וַהֲוָה לִי לְפָרָק דֵין אֱלָהַי וְאֶבְנֵי לֵהּ מַקְדְשָׁא אֱלָהָא דַאֲבָהָתַי וְאֶפְלַח קֳדָמוֹהִי:
@40 יְיָ מָרֵי נִצְחָן קְרָבַיָא יְיָ שְׁמֵהּ:
@41 רְתִכֵּי פַּרְעֹה וּמַשִׁרְיָתֵהּ שְׁדִי בְיַמָא וּשְׁפַר גִבָּרוֹהִי אִטְבָּעוּ בְּיַמָא דְסוּף:
@42 תְּהוֹמַיָא חֲפוֹ עֲלֵיהוֹן נְחָתוּ לְעוּמְקַיָא כְּאַבְנָא:
@43 יַמִינָךְ יְיָ אַדִיר בְּחֵילָא יַמִינָךְ יְיָ תְּבָּרַת סָנְאָה:
@44 וּבִסְגֵי תָקְפָּךְ תְּבַרְתָּנוּן לִדְקָמוּ עַל עַמָךְ שַׁלַחְתָּ רוּגְזָךְ שֵׁיצִנוּן כְּנוּרָא לְקַשָׁא:
@45 וּבְמֵימַר פּוּמָךְ חַכִּימוּ מַיָא קָמוּ כְשׁוּר אֲזָלַיָא קָפוּ תְהוֹמִין בְּלִבָּא דְיַמָא:
@46 דַהֲוָה אֲמַר סָנְאָה אֶרְדוֹף אַדְבֵּק אֲפַלֵג בִּזְתָא תִּשְׂבַּע מִנְהוֹן נַפְשִׁי אֶשְׁלוֹף חַרְבִּי תְּשֵׁיצִינוּן יְדִי:
@47 אֲמַרְתָּ בְּמֵימְרָךְ חֲפָא עֲלֵיהוֹן יַמָא אִשְׁתְּקָעוּ כַּאֲבָרָא בְּמַיִן תַּקִיפִין:
@48 לֵית בַּר מִנָךְ דְאַתְּ הוּא אֱלָהָא יְיָ לֵית בַּר מִנָךְ אֱלָהָא אַתְּ אַדִיר בְּקוּדְשָׁא דָחֵל תֻּשְׁבְּחָן עָבֵד פָּרִישָׁן:
@49 אֲרֵמְתָּ יַמִינָךְ בְּלַעְתְּנוּן אַרְעָא:
@50 דַבַּרְהִי בְטַבְוָתָךְ עַמָא דְנַן דִפְרָקְתָּ סוֹבַרְהִי בְתָקְפָּךְ לְדִירָא דְקֻדְשָׁךְ:
@51 שְׁמָעוּ עַמְמַיָא וְזָעוּ דַחֲלָא אַחֲדָתְנוּן דַהֲווֹ יָתְבִין בִּפְלָשֶׁת:
@52 בְּכֵן אִתְבְּהִילוּ רַבְרְבֵי אֱדוֹם תַּקִיפֵי מוֹאָב אֲחַדָתְנוּן רְתֵיתָא אִתְבָּרוּ כֹּל דַהֲווֹ יָתְבִין בִּכְנָעַן:
@53 תַּפִּיל עֲלֵיהוֹן אֵימְתָא וְדַחַלְתָּא בִּסְגֵי תָקְפָּךְ יִשְׁתְּקוּן כְּאַבְנָא עַד דְיֵעִבַּר עַמָךְ יְיָ יָת אַרְנוֹנָא עַד דְיֵעִבַּר עַמָא דְנַן דִי פְרַקְתָּא יָת יַרְדְנָא:
@54 תָּעֵלִנוּן וְתַשְׁרִינוּן בְּטוּרָא דְאַחְסַנְתָּךְ אֲתַר מְתַקֵן לְבֵית שְׁכִנְתָּךְ אַתְקֵנְתָּא יְיָ מַקְדְשָׁא יְיָ אַתְקְנוֹהִי יְדָיךְ:
@55 יְיָ מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָא:
@56 אֲרֵי עַלוּ סוּסָוַת פַּרְעֹה בִּרְתִכּוֹהִי וּבְפָרָשׁוֹהִי בְּיַמָא וַאֲתֵיב יְיָ עֲלֵיהוֹן יָת מֵי יַמָא וּבְנֵי יִשְׂרָאֵל הַלִיכוּ בְיַבֶּשְׁתָּא בְּגוֹ יַמָא:
@57 וּנְסֵיבַת מִרְיָם נְבִיאֲתָא אֲחָתֵהּ דְאַהֲרֹן יָת תֻּפָּא בִּידַהּ וּנְפָקוּ כָל נְשַׁיָא בַּתְרָהָא בְּתֻפִּין וּבְחִנְגִין:
@58 וּמְעַנְיָא לְהוֹן מִרְיָם שַׁבָּחוּ וְאוֹדוּ קֳדָם יְיָ אֲרֵי אִתְגָאֵי עַל גֵוְתָנַיָא וְגֵאוּתָא דִילֵהּ הִיא סוּסְיָא וְרָכְבֵהּ רְמָא בְיַמָא:
@59 וְאַטֵּל משֶׁה יָת יִשְׂרָאֵל מִיַמָא דְסוּף וּנְפָקוּ לְמַדְבְּרָא דְחַגְרָא וַאֲזָלוּ תְלָתָא יוֹמִין בְּמַדְבְּרָא וְלָא אַשְׁכָּחוּ מַיָא:
@60 וַאֲתוֹ לְמָרָה וְלָא יְכִילוּ לְמִשְׁתֵּי מַיָא מִמָרָה אֲרֵי מְרִירִין אִנוּן עַל כֵּן קְרָא שְׁמַהּ מָרָה:
@61 וְאִתְרָעָמוּ עַמָא עַל משֶׁה לְמֵימַר מָה נִשְׁתֵּי:
@62 וְצַלִי קֳדָם יְיָ וְאַלְפֵהּ יְיָ אָעָא וּרְמָא לְמַיָא וּבַסִימוּ מַיָא תַּמָן גְזַר לֵהּ קְיָם וְדִין וְתַמָן נַסְיֵהּ:
@63 וַאֲמַר אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וּדְכָשַׁר קֳדָמוֹהִי תַעְבֵּד וְתַצֵית לִפִקוּדוֹהִי וְתִטַר כָּל קְיָמוֹהִי כָּל מַרְעִין דִי שַׁוֵיתִי בְמִצְרַיִם לָא אֲשַׁוִנוּן עֲלָךְ אֲרֵי אֲנָא יְיָ אַסָךְ:
@64 וַאֲתוֹ לְאֵילִם וְתַמָן תְּרֵי עֲסַר מַבּוּעִין דְמַיִן וְשִׁבְעִין דִקְלִין וּשְׁרוֹ תַמָן עַל מַיָא:
@65 וּנְטָלוּ מֵאֵילִם וַאֲתוֹ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְּמַדְבְּרָא דְסִין דִי בֵין אֵילִם וּבֵין סִינָי בְּחַמְשַׁת עַסְרָא יוֹמָא לְיַרְחָא תִנְיָנָא לְמִפָּקְהוֹן מֵאַרְעָא דְמִצְרַיִם:
@66 וְאִתְרָעָמוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל עַל משֶׁה וְעַל אַהֲרֹן בְּמַדְבְּרָא:
@67 וַאֲמָרוּ לְהוֹן בְּנֵי יִשְׂרָאֵל לְוַי דְמִיתְנָא קֳדָם יְיָ בְּאַרְעָא דְמִצְרַיִם כַּד הֲוֵינָא יָתְבִין עַל דוּדֵי בִסְרָא כַּד הֲוֵינָא אָכְלִין לַחְמָא וְשָׂבְעִין אֲרֵי אַפֶּקְתּוּן יָתָנָא לְמַדְבְּרָא הָדֵין לְקַטָּלָא יָת כָּל קְהָלָא הָדֵין בְּכַפְנָא:
@68 וַאֲמַר יְיָ לְמשֶׁה הָא אֲנָא מָחֵית לְכוֹן לַחְמָא מִן שְׁמַיָא וְיִפְקוּן עַמָא וְיִלְקְטוּן פִּתְגַם יוֹם בְּיוֹמֵהּ בְּדִיל דַאֲנַסִנוּן הַיְהָכוּן בְּאוֹרַיְתִי אִם לָא:
@69 וִיהֵי בְּיוֹמָא שְׁתִיתָאָה וִיתַקְנוּן יָת דְיַיְתוּן וִיהֵי עַל חַד תְּרֵין עַל דְיִלְקְטוּן יוֹם יוֹם:
@70 וַאֲמַר משֶׁה וְאַהֲרֹן לְכָל בְּנֵי יִשְׂרָאֵל בְּרַמְשָׁא וְתִדְעוּן אֲרֵי יְיָ אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@71 וּבְצַפְרָא וְתֶחֱזוּן יָת יְקָרָא דַיְיָ כַּד שְׁמִיעַ (קֳדָמוֹהִי) יָת תֻּרְעֲמוּתְכוֹן עַל מֵימְרָא דַיְיָ וְנַחְנָא מָא אֲרֵי אַתְרַעַמְתּוּן עֲלָנָא:
@72 וַאֲמַר משֶׁה בִּדְיִתֵּן יְיָ לְכוֹן בְּרַמְשָׁא בִּסְרָא לְמֵיכַל וְלַחְמָא בְּצַפְרָא לְמִסְבַּע בְּדִשְׁמִיעַן קֳדָם יְיָ יָת תֻּרְעֲמוּתְכוֹן דִי אַתּוּן מִתְרַעֲמִין עֲלוֹהִי וְנַחְנָא מָא לָא עֲלָנָא תֻּרְעֲמוּתְכוֹן אֶלָהֵן עַל מֵימְרָא דַיְיָ:
@73 וַאֲמַר משֶׁה לְאַהֲרֹן אֱמַר לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל קְרִיבוּ קֳדָם יְיָ אֲרֵי שְׁמִיעַן קֳדָמוֹהִי יָת תֻּרְעֲמוּתְכוֹן:
@74 וַהֲוָה כַּד מַלִיל אַהֲרֹן עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵלּ וְאִתְפְּנִיוּ לְמַדְבְּרָא וְהָא יְקָרָא דַיְיָ אִתְגְלִי בַּעֲנָנָא:
@75 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@76 שְׁמִיעַ קֳדָמַי יָת תֻּרְעֲמַת בְּנֵי יִשְּׂרָאֵל מַלֵיל עִמְהוֹן לְמֵימַר בֵּין שִׁמְשַׁיָא תֵּיכְלּוּן בִּסְרָא וּבְצַפְרָא תִּשְׂבְּעוּן לַחְמָא וְתִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@77 וַהֲוָה בְרַמְשָׁא וּסְלֵיקַת סְלָיו וַחֲפַת יָת מַשְׁרִיתָא וּבְצַפְרָא הֲוַת נְחָתַת טַלָא סְחוֹר סְחוֹר לְמַשְׁרִיתָא:
@78 וּסְלֵיקַת נְחָתַת טַלָא וְהָא עַל אַפֵּי מַדְבְּרָא דַעְדַק מְקַלַף דַעְדַק כְּגִיר כִּגְלִידָא עַל אַרְעָא:
@79 וַחֲזוֹ בְנֵי יִשְׂרָאֵל וַאֲמָרוּ גְבַר לַאֲחוּהִי מַנָא הוּא אֲרֵי לָא יְדָעוּ מָא הוּא וַאֲמַר משֶׁה לְהוֹן הוּא לַחְמָא דִי יְהַב יְיָ לְכוֹן לְמֵיכַל:
@80 דֵין פִּתְגָמָא דִי פַקֵיד יְיָ לְקוּטוּ מִנֵהּ גְבַר לְפוּם מֵיכְלֵהּ עֻמְרָא לְגֻלְגַלְתָּא מִנְיַן נַפְשָׁתֵיכוֹן גְבַר לְדִי בְמַשְׁכְּנֵהּ תִּסְבוּן:
@81 וַעַבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וּלְקָטוּ דְאַסְגֵי וּדְאַזְעֵר:
@82 וּכְלוֹ בְעוּמְרָא וְלָא אוֹתַר דְאַסְגֵי וּדְאַזְעֵר לָא חַסִיר גְבַר לְפוּם מֵיכְלֵהּ לְקָטוּ:
@83 וַאֲמַר משֶׁה לְהוֹן אֱנַשׁ לָא יַשְׁאַר מִנֵהּ עַד צַפְרָא:
@84 וְלָא קַבִּילוּ מִן משֶׁה וְאַשְׁאָרוּ גֻבְרַיָא מִנֵה עַד צַפְרָא וּרְחֵשׁ רִיחֲשָׁא וּסְרִי וּרְגַז עֲלֵיהוֹן משֶׁה:
@85 וּלְקָטוּ יָתֵהּ בִּצְפַר בִּצְפָר גְבַר לְפוּם מֵיכְלֵהּ וּמָא דְמִשְׁתָּאַר מִנֵהּ עַל אַפֵּי חַקְלָא כַּד חֲמָא עֲלוֹהִי שִׁמְשָׁא פָּשָׁר:
@86 וַהֲוָה בְּיוֹמָא שְׁתִיתָאָה לְקָטוּ לַחְמָא עַל חַד תְּרֵין תְּרֵין עֻמְרִין לְחָד וַאֲתוֹ כָּל רַבְרְבֵי כְנִשְׁתָּא וְחַוִיאוּ לְמשֶׁה:
@87 וַאֲמַר לְהוֹן הוּא דִי מַלִיל יְיָ שְׁבָתָא שְׁבַת קוּדְשָׁא קֳדָם יְיָ מְחָר יָת דִי אַתּוּן עֲתִידִין לְמֵפָא אֲפוֹ וְיָת דִי אַתּוּן עֲתִידִין לְבַשָׁלָא בַּשִׁילוּ וְיָת כָּל מוֹתָרָא אַצְנָעוּ לְכוֹן לְמַטְּרַת עַד צַפְרָא:
@88 וְאַצְנָעוּ יָתֵהּ עַד צַפְרָא כְּמָא דְפַקִיד משֶׁה וְלָא סְרִי וְרִיחֲשָׁא לָא הֲוָה בֵהּ:
@89 וַאֲמַר משֶׁה אִכְלוּהִי יוֹמָא דֵין אֲרֵי שַׁבְּתָא יוֹמָא דֵין קֳדָם יְיָ יוֹמָא דֵין לָא תַשְׁכְּחֻנֵהּ בְּחַקְלָא:
@90 שִׁתָּא יוֹמִין תִּלְקְטֻנֵהּ וּבְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא לָא יְהֵי בֵהּ:
@91 וַהֲוָה בְּיוֹמָא שְׁבִיעָאָה נְפָקוּ מִן עַמָא לְמִלְקָטּ וְלָא אַשְׁכָּחוּ:
@92 וַאֲמַר יְיָ לְמשֶׁה עַד אֵימָתַי אַתּוּן מְסָרְבִין לְמִטַר פִּקוּדַי וְאוֹרָיָתַי:
@93 חֲזוֹ אֲרֵי יְיָ יְהַב לְכוֹן שַׁבְּתָא עַל כֵּן הוּא יָהֵב לְכוֹן בְּיוֹמָא שְׁתִיתָאָה לְחֵם תְּרֵין יוֹמִין תִּיבוּ אֲנַשׁ תְּחוֹתוֹהִי לָא יִפּוֹק אֲנַשׁ מֵאַתְרֵהּ בְּיוֹמָא שְׁבִיעָאָה:
@94 וְנָחוּ עַמָא בְּיוֹמָא שְׁבִיעָאָה:
@95 וּקְרוֹ בֵית יִשְׂרָאֵל יָת שְׁמֵהּ מָן וְהוּא כְּבַר זְרַע גִדָא חִוָר וְטַעְמֵה כְּאִסְקְרֵיטָוָן בִּדְבָשׁ:
@96 וַאֲמַר משֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ מִלֵי עֻמְרָא מִנֵהּ לְמַטְרָא לְדָרֵיכוֹן בְּדִיל דְיֶחְזוּן יָת לַחְמָא דִי אוֹכָלִית יָתְכוֹן בְּמַדְבְּרָא בְּאַפָּקוּתִי יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@97 וַאֲמַר משֶׁה לְאַהֲרֹן סַב צְלוֹחִית חֲדָא וְהַב תַמָן מְלֵי עֻמְרָא מָן וְאַצְנַע יָתֵהּ קֳדָם יְיָ לְמַטְרָא לְדָרֵיכוֹן:
@98 כְּמָא דִי פַקִיד יְיָ לְמשֶׁה וְאַצְנְעֵהּ אַהֲרֹן קֳדָם סַהֲדוּתָא לְמַטְרָא:
@99 וּבְנֵי יִשְׂרָאֵל אֲכָלוּ יָת מַנָא אַרְבְּעִין שְׁנִין עַד דְמֵיתֵיהוֹן לְאַרְעָא יָתְבָתָא יָת מַנָא אֲכָלוּ עַד דְאָתוֹ לִסְיָפֵי אַרְעָא דִכְנָעַן:
@100 וְעֻמְרָא חַד מִן עַסְרָא בִּתְלָת סְאִין הוּא:
@101 וּנְטָלוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִמַדְבְּרָא דְסִין לְמַטְלָנֵיהוֹן עַל מֵימְרָא דַיְיָ וּשְׁרוֹ בִּרְפִידִים וְלֵית מַיָא לְמִשְׁתֵּי עַמָא:
@102 וּנְצָא עַמָא עִם משֶׁה וַאֲמָרוּ הָבוּ לָנָא מַיָא וְנִשְׁתֵּי וַאֲמַר לְהוֹן משֶׁה מָא אַתּוּן נָצָן עִמִי מָא מְנַסוּן אַתּוּן קֳדָם יְיָ:
@103 וּצְחִי תַמָן עַמָא לְמַיָא וְאִתְרַעַם עַמָא עַל משֶׁה וַאֲמַר לְמָא דְנַן אַסֶקְתָּנָא מִמִצְרַיִם לְקַטָלָא יָתִי וְיָת בָּנַי וְיָת בְּעִירַי בְּצָחוּתָא:
@104 וְצַלִי משֶׁה קֳדָם יְיָ לְמֵימַר מָא אֶעְבֵּד לְעַמָא הָדֵין עוֹד זְעֵיר פּוֹן וְיִרְגְמֻנִי:
@105 וַאֲמַר יְיָ לְמשֶׁה עִבַּר קֳדָם עַמָא וּדְבַר עִמָךְ מִסָבֵי יִשְׂרָאֵל וְחֻטְרָךְ דִי מָחֵיתָא בֵהּ יָת נַהֲרָא סַב בִּידָךְ וְתֵיזִל:
@106 הָא אֲנָא קָאֵם קֳדָמָךְ תַּמָן עַל טִנָרָא בְּחוֹרֵב וְתִמְחֵי בְטִנָרָא וְיִפְּקוּן מִנֵהּ מַיָא וְיִשְׁתֵּי עַמָא וַעֲבַד כֵּן משֶׁה לְעֵינֵי סָבֵי יִשְׂרָאֵל:
@107 וּקְרָא שְׁמָא דְאַתְרָא נִסֵיתָא וּמַצוּתָא עַל דִנְצוֹ בְּנֵי יִשְׂרָאֵל וְעַל דְנַסִיאוּ קֳדָם יְיָ לְמֵימַר הֲאִית שְׁכִינְתָּא דַיְיָ בֵּינָנָא אִם לָא:
@108 וַאֲתָא עֲמָלֵק וַאֲגַח קְרָבָא עִם יִשְׂרָאֵל בִּרְפִידִם:
@109 וַאֲמַר משֶׁה לִיהוֹשֻׁעַ בְּחַר לָנָא גֻבְרַיָא וּפוּק אֲגַח קְרָבָא בַּעֲמָלֵק מְחָר אֲנָא קָאֵם עַל רֵישׁ רָמָתָא וְחוּטְרָא דְאִתְעֲבִידוּ בֵהּ נִסִין מִן קֳדָם יְיָ בִּידִי:
@110 וַעֲבַד יְהוֹשֻׁעַ כְּמָא דְאֲמַר לֵהּ משֶׁה לְאַגָחָא קְרָבָא בַּעֲמָלֵק וּמשֶׁה אַהֲרֹן וְחוּר סְלִיקוּ לְרֵישׁ רָמָתָא:
@111 וַהֲוִי כַּד יְרִים משֶׁה יְדוֹהִי וּמִתְגַבְּרִין דְבֵית יִשְׂרָאֵל וְכַד מַנַח יְדוֹהִי וּמִתְגַבְּרִין דְבֵית עֲמָלֵק:
@112 וִידֵי משֶׁה יְקָרָן וּנְסִיבוּ אַבְנָא וְשַׁוִיאוּ תְחוֹתוֹהִי וִיתֵב עֲלַהּ וְאַהֲרֹן וְחוּר סַעְדָן בִּידוֹהִי מִכָּא חַד וּמִכָּא חַד וַהֲוָה יְדוֹהִי פְּרִיסָן בִּצְלוֹ עַד דְעַל שִׁמְשָׁא:
@113 וְתַבַּר יְהוֹשֻׁעַ יָת עֲמָלֵק וְיָת עַמֵהּ לְפִתְגָם דְחָרֶב:
@114 וַאֲמַר יְיָ לְמשֶׁה כְּתָב דָא דוּכְרָנָא בְּסִפְרָא וְשַׁוִי קֳדָם יְהוֹשֻׁעַ אֲרֵי מִמְחָא אֶמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא:
@115 וּבְנָא משֶׁה מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם יְיָ דַעֲבַד לֵהּ נִסִין:
@116 וַאֲמַר בִּשְׁבוּעָה אֲמִירָא דָא מִן קֳדָם דְחֵילָא דִשְׁכִנְתֵּהּ עַל כָּרְסֵהּ יְקָרֵהּ דְעָתִיד דְאִתָּגַח קְרָבָא קֳדָם יְיָ בִּדְבֵית עֲמָּלֵק לְשֵׁצָיוּתְהוֹן מִדָרֵי עָלְמָא: פפפ:

@1 **ויהי בשלח וגו'**. צריך לדעת למה אמר לשון צער במקום גילה ורנן. עוד למה כינה הענין בפרעה ולא באדון המעשים כי הוא המוציא אותנו מארץ מצרים. אכן הכתוב יגיד הסיבה שגרמה כל הצער שנצטערו ישראל ברדיפת פרעה, כפה אותו עד שנתרצה ושלחם ואמר להם קומו צאו מזה חשב מחשבות לרדוף אחריהם כאשר אבאר בעזרת השם, ובזה גרם צער לישראל, וגם לעצמו גרם איבוד לו ולאומתו. וצא ולמד כי הקב''ה יקפיד על כליון הנבראים כמובא בדבריהם ז''ל (מגילה י':) מעשה ידי טובעים בים ואתם אומרים שירה. וכנגד כל זה אמר הכתוב ויהי לשון צער, ומי גרם כל צער זה בשלח פרעה, שאם היה ה' מוצאים שלא לרצונו הגם שלא היה חפץ לשלחם לא היה לו מקום לרדוף, אלא עינו הטעתו שהיה הדבר תלוי בו ולזה חשב לשוב לקחתם. ואומרו **ולא נחם** בוא''ו בתחלת הודעת ענין, יכוין תוס' על הגדת צער הקודם הרמוז בתיבת ויהי כנזכר:
@1 **עוד** ירצה על דרך אומרם ז''ל (זהר ח''ב מ''ה:) כי כל מקום שיכנה ישראל בשם עם ירמוז על ערב רב, ולזה תמצא בענין זה לפעמים מזכיר שמם העם ולפעמים מזכירם בני ישראל דכתיב וחמושים עלו בני ישראל וגו' הרי זה מראה באצבע כי העם לא מבני ישראל המה. ואמרו ז''ל (שמות רבה פמ''ב) כי השחתת ישראל במדבר זה הוא סיבתו, הם אמרו נתנה ראש וגו', הם אמרו עשה לנו וגו', וזה הוא אומרו **ויהי** צער גדול לשונאיהם של ישראל **בשלח פרעה את העם** פירוש ערב רב ששלחם פרעה לא ה' ברוך הוא הוציאם כי לא בא אלהים לקחת לו אלא גוי גדול נחלתו יתברך אלא פרעה שלחם, וטעמו היה לכוף את ישראל לשוב מצרים, והם מצאו מקום להדבק בישראל וסובב בתכליתם צער לישראל כנזכר. ולדרך זה ידוייק על נכון אומרו ולא נחם אלהים **כי קרוב הוא** פירוש קרוב הוא לרמוז העם מקרוב בא ואין לו חוזק בקדושה. או קרוב הוא להרשיע ויסובב רעה גם לישראל והרעה היא כי אמר וגו' פן ינחם בראותם, וידוייק על נכון אומרו **ולא נחם** בתוס' וא''ו בתחלת ענין לומר כי זה נוסף על כמה צער שגרמו להם הרמוז בתיבת ויהי וגו' ועוד להם ולא נחם:
@1 **עוד** ירצה על דרך אומרם ז''ל (שם פ''כ) כי פרעה עשה לישראל לויה, ולפי זה יגיד הכתוב צער הנמשך להם מזה ואמר **ויהי** לשון צער לסיבת שלח פרעה כי יצטרך הדבר להיות שיטול שכר פסיעותיו. וצא ולמד משכר פסיעות של אותו רשע נבוכדנצר (סנהרין צ''ו.) וכל שכר שיקצוב לו ה' יהיה גורם רעה לשונאיהם של ישראל, אשר על כן נתחכם ה' ובטל מצותו ממנו ונתחכם שלא הוליכם דרך קרוב שמן הסתם לשם יערים פרעה ללותם ובזה בטלה מחשבתו כאילו לא ליוה אותם. נמצא מי גרם שלא הלכו ישראל דרך קרוב לווייתו של פרעה, וטעם אומרו **ולא נחם** בתוס' וא''ו לדרך זה לרמוז כי צער אחר גרם הדבר זולת זה שעל כל פנים הגיעו קצת זכות בלויה וזה סיבה שנכנסו ישראל בסכנה ברדיפתו כאמור בדבריהם ז''ל (שמות רבה פכ''א) בפסוק ולא קרב זה וגו' ובפסוק מה תצעק אלי וגו' וכמה הרפתקי דעדו עלייהו. ואומרו **כי אמר** וגו' הוא טעם אחר וכאלו אמר וכי אמר, ותולדות מיחושו הוא לצד שליחת העם שהם ערב רב כמו שרשמנו בדרך ב':
@2 **וחמושים עלו וגו'**. ואולי כי זולת היותם מזויינים בכלי זיין לא יועיל מה שיסב ה' אותם לבל יחזרו בראותם מלחמה כי על כל פנים ישובו מצרימה כיון שאין בידם כלי זיין לערוך עם אויב מלחמה ויראו עצמן אבודים, לזה אמר **וחמושים עלו** וגו' פירוש מלבד טעם שיסב ה' היו להם גם כן כלי זיין ובהצטרפות שני הטעמים **לא ינחם העם בראותם מלחמה וגו'**:
@3 **פקוד יפקוד וגו'**. טעם הכפל להצדיק אמונת הדבר.
@3 וזה שיעורו פקוד פירוש הפקידה שהבטיח ה' ודאי יפקוד. עוד ירצה לרמוז על ב' דברים על הרחקת הנזק היא הצלתם מעוני מצרים ומעול סובלם, והקרבת התועלת שיצאו ברב טוב לבית ישראל דכתיב (בראשית טו, יד) ואחרי כן יצאו ברכוש גדול, וטעם שרמז להם דבר זה לפי שהוא נוגע לשבועה שלא יהיה להם דבר זה סיבה למניעה לבל יעלו עצמותיו לצד שיהיו טרודים באסיפת הון וטעינת כסף וזהב כי ירבה כאומרם ז''ל (בכורות ה':) שאין לך אדם מישראל שלא טען עשרה חמורים מכסף וזהב של מצרים וזה יהיה סיבה למניעת הדבר, לזה אמר **השבע** וגו' **לאמר פקוד יפקוד** גם פקידת העושר ואף על פי כן תדחקו עצמיכם ותסבלו עצמותי הגם שיהיה להם מאמצעות כן הפסד כשיעור משאו מכסף וזהב. ותמצא שכן עשה משה כאומרם ז''ל (שמות רבה פ''כ) שבמקום שיטעון כסף וזהב טען ארונו של יוסף במקומו ונטל שכרו על הדברו:
@3 **מזה אתכם**. טעם אומרו **מזה** אין לומר כי דוקא משום יעלוהו, אלא נתכוון לחזק השבועה שתהיה חזקה כדין הנשבע על דעת חבירו בשביל טובה שעשה לו, ולזה התנה ואמר **מזה** פירוש על דרך אומרם ז''ל (בראשית רבה פ' פ''ד) בפסוק נסעו מזה נסעו מהאחוה שהוא מנין ז''ה, והוא שרמז להם כאן בשעת השבועה באומרו **מזה אתכם** פירוש כי באמצעות חסד זה שהם נשבעים לו מה שהם הפרידוהו מזה ונסעו מאחוותו ועשו מה שעשו לו עכשיו יתוקן הדבר ויהיו לאחדים, והוא אומרו אתכם יהיו חונים מהנסיעה להיות אתם עמם ונעקר העון ההוא והרי הם יחד באחוה, והכוונה בזה כי מחל להם מה שפשעו בו בעד חסד זה שנשבעין לו, וכפ''ז הנה הם נשבעים על דעתו בשביל טובה שעשה להם:
@5 **וה' הולך** וגו'. אומרו **לנחותם** פירוש להיות להם נח הדרך כי לצד שהיו ימי החום חופף ה' עליהם בעמוד ענן לבל יכם השמש. ולזה לא היה משמש עמוד הענן אלא ביום ולא בלילה, וענן זה הוא לבד מענן הקודם להם לישר המעקשים להשפיל הגבוה ולהגביה הנמוך ולהראותם הדרך. ויש ראיה לזה ממה שאמר הכתוב בפרשת דברים (א' ל''ג) ההולך לפניכם בדרך לתור לכם מקום לחנותכם באש לילה לראותכם בדרך אשר תלכו בה ובענין יומם, והנה הזכיר הכתוב ג'. הא' לתור לכם מקום זה היה משמש תמיד לפניהם פירוש מקדים ללכת קודם להם. הב' עמוד האש לראותכם וגו', הג' ובענן יומם, והם דברינו עצמם שענן זה לא היה אלא חופף מהכותם שמש. ולא כמו שפירש''י להנחותם וחסר ה''א והביא חבר לראותכם כי לפי דברינו גם כאן גם שם אינה חסרה ה''א, ועיין בפסוק שאחר זה:
@5 **ולילה וגו' להאיר וגו'**. קשה לפי דבריהם ז''ל (שבת כ''ב:) שאמרו שכל מ' שנה שהיו במדבר לא הלכו אלא לאורו שהיו רואים אפילו מה שבתוך הטפיח, ואין לומר כי על זמן הלילה הוא אומר שאין זה פשט אומרם לא הלכו אלא לאורו כי מה בא למעט אם לא שנא' אור השמש ביום ואם כן הלילה למה לא יאיר כיום שלא היו צריכין לשמש שהוצרך לעמוד אש להאיר להם. ולהבין הענין יש לדקדק עוד אומרו **ללכת יומם ולילה** למה לא הספיק טעם להאיר להם שהוצרך לומר ללכת וגו':
@5 **אכן** כוונת הדברים היא לעולם שלא זז אורו יתברך ממחנה ישראל תמיד כמאמר חכמינו ז''ל שכתבנו בסמוך אלא שיש לדעת כי האור הקדוש הלזה לא היה מתפשט חוץ ממחנה ישראל אלא דוקא במושבותם. ויש טעם בדבר ומה גם במדבר הרע שהוא מדור של מחנה טומאה כי שם הרגיעה הקליפה כידוע בדברי הקדושים (זהר ח''א קכ''ו.) וכיון שכן לא היו ישראל יכולים ליהנות מהאור העליון אלא במחניהם אבל חוץ למחניהם לילה יחשיך כסדר העולם. והנה אם לא היו ישראל הולכים בלילה כשיחפוץ ה' ללכת לא היו צריכין לאור עמוד האש כי לכל בני ישראל היה אור ה' במושבותם אלא לסיבת הליכתם בלילה הוצרכו לעמוד להאיר למרחוק חוץ למחנה ישראל להכיר מקום שיכלו בו חוץ למחניהם, והוא אומרו **להאיר להם**, וטעם אור זה הוא **ללכת יומם ולילה** פירוש בשוה כשם שביום מלבד אור ה' הנוצץ עליהם היו רואים אור למרחוק באור השמש המאיר לעולם כולו כמו כן היו רואים בלילה באמצעות עמוד האש. ובזה יטעם ביאור מה שאמר הכתוב בפרשת דברים באש לילה לראותכם בדרך אשר תלכו בה פירוש לראותכם כדי לראותכם. כדי שתראו אותם, לא כמו שפירש''י להראותכם וחסר ה''א והביא מהנביאים ומהכתובים חבר לה כין אנו צריכים לזה, וביאר הכ' דבריו כי דברינו יגיד באומרו לראותכם בדרך ולדבריו היה צריך לומר הדרך, אלא הכוונה היא להיות שהיה להם לישראל אור עולם במושבותם ולא בדרך אשר עדיין לא באו שמה לזה אמר כי עמוד [אש] טעמו הוא כדי שיראו בדרך אשר ילכו בה לשון עתיד והבן והם דברינו עצמם. ומעתה אין הבדל בין היום ללילה לבני ישראל ולא היו מכירים זמן יום וזמן לילה אלא על ידי השתנות העננים:
@8 **דבר וגו' וישובו וגו'**. הנה כל רואה יקהה בזה למה יצטרך ה' להערים חם ושלום על הדבר והוא עשה יעשה כל אשר יחפוץ בלב פרעה לרדוף:
@8 **אכן** בהשכיל במה שקדם לנו בידיעת מדת הבורא כי חפץ למען צדק ישראל הלא זה הדבר אשר דבר ה' במצוה זו שנתחכם לבל יכשלו בהכעסה לבורא ויאמרו דברי ניאוץ שאמרו אחר כך (פסוק יא) המבלי אין קברים וגו' הלא וגו' טוב לנו עבוד את מצרים וגו' ונתחכם ה' ועשה דבר מורגש ומוכר להם כי ה' יעץ על פרעה רעה ומתחכם אליו להוציאו ממצרים לרדוף את ישראל להכבד בו. ומעתה אין מקום לישראל לחוש לפרעה ואדרבה יחילו דרכיו לראות נקמתם בו, ולא הספיק לבורא לומר להם הדברים בפה לבד כי הוא יחזק לב פרעה לרדוף אחריהם כי לא יעשו הדברים בהם רושם ובראות אותו ירעשו ויתנו ראש לשוב אליו ממוראו עליהם, לזה צוה ה' שישובו ויחנו ויעשו מעשה המוכן לרדוף פרעה אחריהם ודבר זה ירגישם ויעשה בהם רושם כי הם הם העושים הכנה בהרגשה רעושה שחזרו לאחוריהם ולחנות במקום מיוחד שממנו יטעה פרעה לרדוף אותם ובזה לא יפחד לבם ובבואו יגל יעקב ישמח ישראל כי יחזה נקם באויבו, ותמצא שאף על פי כן לא הועיל בהחלט. וצא ולמד מה שאמרו בראותו ומזה תקיש מה היו עושים זולת החזרה והבן:
@9 **ואמר פרעה וגו'**. פירוש כשישוב המגיד הוא יודיעו כל אשר ראו עיניו:
@11 **ויגד למלך וגו' כי ברח וגו' ויהפך לבב וגו' אל העם**. צריך לדעת אומרו כי ברח ולא אמר כי הלך שיראה שראו בהם סימן בריחה. עוד קשה אומרו **ויהפך** וגו' משמע שנתחרטו על הדבר אשר עשוהו והדברים תמוהים וכי לרצונם עשו והלא הוכו מכות גדולות עד כמעט ספו ותמו ובעל כרחו שלחום ואיך יהפך לבם בדבר שלא לרצונם עשוהו, וקשה עוד אומרם **מה זאת עשינו** וגו' כמתרעמים על עצמם על עשות דבר שלא כהוגן והלא לא עשו אלא בעל כרחם ומה יתאונן אדם על דבר שעשאו בעל כרחם. ואפשר לומר על דרך מאמרם ז''ל (זהר ח''ב מ''ה:) כי העם הוא ערב רב וכמו שכתבנו בתחלת הפרשה ופירוש הכתוב כך הוא ויוגד למלך מצרים כי ברח העם פירוש העם אשר שלח הוא עם ישראל לטעם נכון אצלו להשיב בני ישראל הן עתה ברחו והלכו להם ולאלו יתיחס הבריחה כי זולת הבריחה אין מצילם מיד פרעה כי הם עמו ועבדיו, **ויהפך לבב פרעה** וגו' פירוש שנחמו על אשר שלחום פירוש לעם לא על ישראל, ויאמרו מה זאת עשינו פירוש תמוהים הם על מעשיהם ששלחו העם, וטעם התמיהה הוא כי שלחנו את ישראל מעבדנו פירושו על דרך אומרם ז''ל (ילקוט ר''ח) כי פרעה כתב גט שחרור לישראל ואמר להם הרי אתם לעצמיכם הרי אתם בני חורין, והוא אומרו **שלחנו** בגט שילוחים, **מעבדנו** שאין להם משפט עבד, והגם שאפשר שעלה על דעתם שיחזרו לא יעבוד בהם עוד עבודת עבד, וכיון שכן תחזור העבודה הצריכה למלך על העם, ומעתה כיון שברח העם מי יעבוד. גם בזה רמז למה לא חששו על בריחת העם הנזכר כשירגישו שתכבד העבודה עליהם, ולזה תיכף ומיד הכינו עצמם לרדוף, והנה לפי מה שפירשתי אין הרדיפה אלא על העם ואמר הכתוב כי ה' חזק לבו של פרעה וירדוף גם אחרי בני ישראל ולא לעם בלבד:
@11 **עוד** נראה על פי מה שפירשתי בפרשת בא (י' ז') כי טעם שהקשו ערפם פרעה ועבדיו הוא לחושבם כי דברי ה' בדרך זה הם דרך ערמה וזה יגיד כי לא יוכל עשות כל חפצו חם ושלום, והנה ביום הכות ה' אותם מכת בכורות וימדדם פגרים מתים רעשו ורעדו והצדיקו הדברים כי אלהי ישראל כל יכול להחריב עולם ומכל שכן מצרים ולפי סברא זו יתחייבו לומר כי מה שאמר ה' דרך ג' ימים אין ערמה חס ושלום אלא אמת יהגה והוכחת פרעה ממה שהולכים כלם יחד אינה הוכחה כטעם האמור בדברי משה (שם) כי חג ה' וגו' וזה היה להם למשען שהשאילו ממונם לישראל והונם כי נתחזק בלבם כי שוב ישובו ישראל מצרים, גם לא חששו כי עשה ה' הדבר בדרך זה כדי שישאילום לצד שהכירו שהי' ה' יכול להכריחם גם על זה לתת כל ממונם, ומה גם לדבריהם ז''ל (שמות רבה פי''ד) שגילו מצפוניהם בימי חושך מצרים וידעו מצרים בזה ואם כן מטעם זה היה להם ליטול הכל באין רואה, וכאשר הגיד המגיד לפרעה אמר אליו כי ברח העם פירוש לפי מה שעלה במסקנתם כפי ההוכחות כי מה' לא היה הדבר בהחלט הליכות עולם אם כן מה שלא רצו ישראל לחזור כי רצו לברוח ממצרים וללכת הליכה מוחלטת ולא מן ה' הוא הדבר, לזה **ויהפך לבב פרעה ועבדיו אל העם** פירוש לא לצד המוציא כי המוציא עדיין בחזקת כי לא הוציא אלא לשעה אלא למה שנוגע לעם למה לא חששו להם. שיברחו, והוא אומרם **מה זאת עשינו כי שלחנו את ישראל מעבדנו** פירוש הגם שהיה לנו לשולחם לגזירת אלהיהם אף על פי כן לא היינו שולחים אותם בדרך זה שיוכלו לברוח מעכדנו, כי היו יכולין לשלוח עמהם חיל מצרים ורכבו ופרשיו עד עבוד אלהיהם במדבר וישובו למצרים:
@11 **או** יאמר כי באמצעות המגיד שהגיד שברחו נתהפך לבב פרעה על מה שהכריעו כי אלהי ישראל כל יכול והרי זה לך האות בבירור כי לא יכול על הכל ממה שדבר דרך ערמה אמור מעתה במופת חותך כי לא היה בו חס ושלום כח להוציאם בהחלט והוצרך לגניבת דעת, ודקדק הכתוב לומר.
@11 **לבב** לומר כי ב' לבבות הוכרעו בדבר כי הגם שבתחלה קודם שלח ישראל היה חושב מחשבה זו כי אין כח בידו להוציאם בהחלט ממה ששואל בדרך זה אף על פי כן היה לו לב אחר דוחה סברא זו ואומר אולי כי אינו חפץ בהם אלא לשעה, ומעתה פרחה לה טענה זו והסכימו ב' הלבבות יחד אל העם לבלתי שלחם שהוברר אצלם צד האחר. ואמרו מה פעולה רעה זאת עשינו כי שלחנו וגו' שלמפרע אנו רואים שלא היה יכול להוציאם בהחלט מטעם שכתבנו לזה ויאסר את רכב ו:
@12 **ואת עמו לקח וגו'**. כי לא היה במשא ומתן שכתבנו אלא הוא ועבדיו אבל עמו הוצרך לקחתם בדברים כי הם היו יראים לנפשם:
@14 **ויחזק וגו' ובני ישראל יוצאים וגו'**. פירוש הוצרך ה' לחזק לבו כי היה לו לתת לב לאופן וסדר יציאת בני ישראל שהיתה ביד רמה וזה יגיד כי פסקה יד מושל מעליהם ומזה היה לו להיות נרתע אלא שה' חזק לבו וחשב מחשבות הנזכר למעלה וירדוף וגו':
@16 **ופרעה הקריב וגו' והנה מצרים וגו'**. צריך לדקדק למה הוצרך לומר זה ולא הספיק מה שקדם לומר וישיגו אותם וגו'. ואמר עוד והנה מצרים נוסע וגו' גם למה התחיל הסיבה בפרעה וגמר אומר במצרים דכתיב והנה מצרים שהיה לו לומר והנה פרעה וגו'. עוד צריך לדקדק אמרו **נוסע** לשון יחיד וגו' על מצרים שהם רבים. ולהבין הכתוב יש להעיר הערה גדולה בדברי בני ישראל אל משה המבלי אין קברים וגו' מה זאת עשית לנו וגו' כנשמע שהדבר להם חדש ואין זה אמת כי כבר הודיעם ה' כי יחזק לבו לרדוף להכבד בו והעירם בזה במעשה אשר צוה להם עשות שישובו ויחנו וגו' כדי שיטעה לרדוף אחריהם ויעשו כן הרי הכינו עצמם להטעותו לרדוף אחריהם אם כן מנין נכנס להם הפחד, לו יהיה שראו שבא בכח גדול שש מאות רכב וגו' אשר אפשר כי לא חשבו מקודם שהיו להם כל כך חוזק אף על פי כן כבר הבטיחם ה' כי הוא המחזק לבו להכבד בו והם סייעו בדבר:
@16 **אכן** יתבאר על פי דבריהם ז''ל (שמות דבה פכ''א) שאמרו וזה לשונם ומצרים נוסע אחריהם זה שר של מצרים מצרים שמו עכ''ל, והנה המלאך הלז בא עמהם כי כן הוא הנהוג שהשר יעזור לאומתו ויפול בנפילתה וצא ולמד ממעשה אלכסנדרום מוקדון (יומא ס''ט:) שהיה נדמה לו שרו במלחמות, והנה מן הסתם כי השר יהיה עומד לימין המלך לא לפני העם, והנה מסדר הרגיל במלחמות שהמלך ביניהם שהעם יקדמו קודם למלך והמלך לבסוף מהעם, וכאן הודיע הכתוב הדבר שממנו באה ההרגשה לישראל לירא ולפחד הגם שקדם להם מה שקדם מהידיעה, ואמר **ופרעה הקריב** פירוש לא עשה סדר הרגיל להקדים העם אלא הקריב עצמו קודם לעם, **וישאו בני ישראל את עיניהם והנה מצרים** פירוש שר של מצרים כנזכר פירוש לצד שפרעה הקריב והשר היה לפניו עומד זה היה סיבה לראות ישראל השר ששמו מצרים נוסע וגו' והם לא יוכלו דעת סיבת השר שאינו אלא לעמוד לפני מלך כנהוג כי אין מנהג המלך להקדים למחנה והם ראו השר נוסע אחריהם פירוש קודם המחנה, לזה רעשו כי חשבו כי שרי מעלה באו לערוך עמם מלחמה, והגם שקדם להם מה שקדם לא הספיק להם כשראו מלאכים באו להלחם עמהם כי הוא אות כי ה' חזר ממחשבתו הטובה כי זולת זה לא היה מסכים על מלאכו לבא כנגדם ולזה צעקו וגו'. ואילו לא היה פרעה מקדים או אם היה סדר הרגיל שיקדים המלך הם היו תולים הדבר כי לא למלחמה בא אלא לעמוד לפני המלך כחוק שרי מעלה עם כל מלכים אשר הם ממונים עליהם ולא היו מפחדים, ובזה נתיישב הענין ויישוב הכתובים. וטעם שלא מנע ה' המלאך מבא, לב' טעמים, הא' כדי להורגו לפניהם כאומרו וירא ישראל את מצרים מת על שפת הים ואמרו ז''ל (זהר ח''ב נ''ב:) שיכוין על השר ששמו מצרים, וטעם ב' אלהים חשבה לטובה כדי שיפחדו ויחזרו בתשובה שלימה ויקרבו לבם לשמים כדי שבאמצעות זה יעשה ה' להם הנס העצום של קריעת ים סוף ודבר זה לא הובטחו בו קודם. ותמצא שדרשו ז''ל (שמות רבה פכ''א) בתיבת הקריב ולא אמר קרב ירצה שהקריב לבן של ישראל לאביהם שבשמים, וכן היה דכתיב **ויצעקו בני ישראל אל ה'**:
@19 **התיצבו וראו**. אולי שנתכוון לומר להם שיתיצבו בתפלה כמות שהיו עומדים וצועקים אל ה' כאמור בסמוך ויצעקו וגו' אל ה', וכן הוא אומר (שמואל א' א') אני האשה הנצבת עמכה וגו':
@19 **אשר יעשה לכם היום**. נתכוון באומרו **היום** להסיר מלבם חשש מה שעבר ביציאת מצרים שארך קץ הגאולה מיום שהתחילה הבשורה עד גמר הדבר שנים עשר חדש, לזה אמר להם כי לא יאריך זמן מלחמה זו אלא הן היום יעשה ה' התשועה:
@19 **אשר** ראיתם את מצרים וגו' כוונת מאמר זה אפשר שנתכוון להסיר מהם הפחד על זה הדרך באומרו הלא מה שראיתם את מצרים היום הוא לצד שלא תוסיפו לראותם עוד עד עולם לטעם זה הוא שהביאם ה' והראה ה' אותם לכם כדי שלא ישאר לכם שום מיחוש מהם לעולם, והוא מאמר הקודם שאמר להם (פסוק ד') וחזקתי את לב פרעה וגו', והגם שראו השר, גם אותו יתמדד לפניהם כמו שכן היה:
@20 ה' **ילחם לכם**. פירוש לצד שהפחד שנפל אליהם הוא מהשר וכמו שפירשנו בפסוק ופרעה הקריב לזה אמר להם בשלמא אם היו הם הלוחמים ישערו כי עצום הוא מהם מה שאין כן לצד שה' הוא הלוחם אין לחוש לאלף כיוצא בו:
@20 **עוד** ירצה לומר שאפילו מדת הרחמים תהפך לדין על המצריים להלחם עמהם, ודקדק לומר **לכם** כיון שבערך ישראל יחשב הדבר רחמים. עוד ירצה **ילחם לכם** כי לא לעזרה לבד יהיה להם במלחמה אלא הוא יערוך כל המלחמה. ואומרו **ואתם תחרישון** יתבאר על דרך אומרם ז''ל (פתיחתא דאיכה רבתי ל') ד' צדיקים מה ששאל זה לא שאל זה וחלוקה המעולה שבכולן הוא מה ששאל חזקיה שאמר אני אין בי כח לא להרוג ולא לרדוף ולא להתפלל אלא אני ישן על מטתי ואתה עושה וכן עשה ה' דכתיב (מלכים ב' י''ט) בלילה ההוא ויצא מלאך ה' וגו' והיא המדריגה שאמר משה ואתם תחרישון פירוש אפילו בתפלה אם אין בכם כח כמאמר חזקיה תחרישון והוא ילחם לכם. ולפי מה שפירשנו בפסוק התיצבו שאמר להם יעמדו בתפלה ירצה על זה הדרך **ואתם תחרישון** למדת הדין פירוש תרבו בתפלה להשמיע במרום קולכם להחריש למדת הדין עליכם:
@21 **מה תצעק אלי**. קשה ולמול מי יצעק אם לא לה' אלהיו ובפרט בעת צרה דכתיב (יונה ב') קראת מצרה לי, (תהלים קי''ח) מן המצר קראתי יה, ואם לצד שהרבה להתפלל הלא כל עוד שלא נענה מהעונה בצר לו לא ירף מתפלה. עוד רואני כי נתקבלה תפלתו ואמר לו ה' **הרם את מטך** וגו' אם כן קבלנות זה שאמר **מה תצעק אלי** למה. עוד קשה אומרו **דבר אל בני ישראל ויסעו** להיכן יסעו אם רודף מאחור והים לפניהם, ואם הכוונה אחר שיבקע הים אם כן היה לו לומר הרם את מטך וגו' ואחר כך יאמר דבר אל בני ישראל וגו':
@21 **אכן** יתבאר הענין על פי מאמרם ז''ל (שמות רבה פכ''א) שישראל היו נתונין בדין מה אלו אף אלו, ודבר ידוע הוא כי כח הרחמים הוא מעשים טובים אשר יעשה האדם למטה יוסיפו כח במדת הרחמים ולהיפך ב''מ ימעיטו הכח, והוא אומרו (דברים לב יח) צור ילדך תשי, והנה לצד שראה אל עליון כי ישראל קטרגה עליהם מדת הדין, והן אמת כי חפץ ה' לצדק ישראל אבל אין כח ברחמים לצד מעשיהם כנזכר, אשר על כן אמר למשה תשובה נצחת **מה תצעק אלי** פירוש כי אין הדבר תלוי בידי הגם שאני חפץ עשות נס כיון שהם אינם ראוים מדת הדין מונעת ואין כח ברחמים כנגד מדת הדין המונעת, ואמר אליו **דבר אל בני ישראל** פירוש זאת העצה היעוצה להגביר צד החסד והרחמים דבר אל בני ישראל ויתעצמו באמונה בכל לבם ויסעו אל הים קודם שיחלק על סמך הבטחון כי אני אעשה להם נם ובאמצעות זה תתגבר הרחמים **ואתה הרם את מטך** פירוש באמצעות מעשה הטוב נעשה להם הנם ובקע הים כי גדול הבטחון והאמונה הלז להכריעם לטובה. ותמצא שכן היה וצדיק הראשון הוא נחשון בן עמינדב ונכנס עד גרונו ולא נבקע הים עד שאמר כי באו מים עד נפש כמאמרם ז''ל (סוטה ל''ז.) ובזה נתישבו הכתובים על נכון. ונראה לי לומר כי רשם ה' לומר להם טעם תגבורת הדין עליהם לצד שהם המעיטו בלבם האמונה ואמרו הלא טוב לנו את עבוד מצרים לזה צוה ה' לעשות כנגד עון זה הצדקת האמונה בכל תוקף. גם בזה רמזם לדעת הסובב תגבורת הדין מחדש:
@23 **ואני הנני מחזק וגו'**. בחמלת ה' עליהם נתכוון להודיעם קודם לבל יפחדו בראותם כי הים נשאר חלוק לפני המצריים כסדר שהיה חלוק לפניהם ישובו לחשוב מחשבות ולהמעיט האמונה בלבם ויאמרו הנה המה עולים אחרינו וייראו מאד לזה הודיעם ואמר להם דעו לכם כי ממני היו הדברים להכבד בו ואני פורש רשת לרגליהם:
@25 **ויסע מלאך האלהים וגו'**. יאיר נתיב כתוב זה במה שפירשנו בפסוק (י''ג כ''א) וה' הולך לפניהם וגו' כי ג' עננים היו משמשים לישראל, א' לפניהם לתור להם מקום וגו', והב' להגין עליהם מחום השמש, והג' להאיר להם בלילה, והודיענו הכתוב אשר עשה ה' בלילה ההוא **ויסע מלאך האלהים** שהוא ההולך לפניהם והוא הענן הראשון שמוזכר בפרשה דברים (א' ל''ג) שאמר ההולך לפניכם נסע והלך לאחריהם, ואמר עוד כי הענן המשמש בפניהם שזמנו כל היום שהגיע זמנו לנסוע בלילה והוא המוזכר בפרשה דברים דכתיב (שם) ובענן יומם גם הוא נסע ועמד לאחריהם, נמצאת אומר כי ב' עננים שהיו לפניהם נסעו לאחריהם, וטעם הב' כדי שיחשיך לפניהם בלתי דעת מקום תחנותם של ישראל, והוא אומרו **ויהי הענן והחשך ויאר את הלילה** פירוש כי הוצרך לשניהם להחשיך בפניהם לבל ידעו מחנה ישראל שהיה בו אורה הלילה והאור יגיד להם מקום לזה כיסה חושך פניהם ולא הספיק לו חשך לבד כי יבהיק אור בני ישראל במושבותם לזה עשה ה' ב' הענן והחשך:
@26 **ויבא בין מחנה מצרים וגו'**. אולי כי כל מקום החלל שבין ב' המחנות מילא אותם הענן והחשך, והוא אומרו **ויבא בין** וגו' שאם לא כן למה הוצרך לומר ויבא בין וגו' אחר שכבר אמר וילך מאחריהם ויעמוד מאחריהם:
@27 **ויט משה את ידו וגו'**. הגם שאמר הכתוב ויולך ה' וגו' וישם את הים לחרבה, לא שם לחרבה אלא מים העמוקים כדי שלא יבקעו כל מי הים ויצטרכו ישראל לרדת למעמקים ויאריכו בהליכה וביגיעה ולזה הקדים רוח קדים להקפות עמקי המים, והוא אומרו (לקמן ט''ו ח') קפאו תהומות בלב ים, וחלק שלא נקפא נבקע, ואם לא היה טעם זה לא היה צריך לרוח קדים. ויש לדעת אימתי היתה נטית ידו של משה אם בתחלת הלילה אם בסופו, והנה משטח הכתוב מוכח כי קודם הבוקר היתה, וקשה דאם כן אין היכר לקריעת ים סוף שהיתה על ידי משה, על כן מוכרח לומר שפירוש הכתוב הוא ויט משה וגו' וכבר הוליך ה' וגו' וישם את הים לחרבה ולזה כשנטה ידו בקעו המים, וכפי זה תכף לנטית ידו נבקע הים. וזה מכוון למה שפירשתי בפסוק (ט''ו) מה תצעק אלי שלא נטה ידו אלא אחר נסיעת ישראל ותכף לכניסת ישראל לים נטה ידו ובקעו, וכן הוא ברבות (שמות רבה פכ''א) וז''ל מיד כיון שהרים משה ידו על הים נבקע עד כאן, או ירצה אומרו **וישם את הים לחרבה** פירוש כל מי הים נגלדו ובנטית יד משה נבקעו המים הגלודים כשיעור שלא יצטרכו לירד לעמקי ים ולעולם רוח קדים שם כל מי הים לחרבה וראשון עיקר:
@27 **כל הלילה**. פירוש עד סוף הלילה ואז נקרע הים וירדו ישראל באשמורת הבוקר:
@28 **בתוך הים ביבשה**. פירוש אומרו בתוך הים בפנימיותו, ואומרו **ביבשה** שלא היה קרקעית הים טיט ורפש:
@28 **והמים להם חומה וגו'**. פירוש כי חלק מהמים שנחלק לא נשפך לצדדין. ואומרו מימינם לומר כי לא חומה ממש שהוא בהקף מהצדדין:
@29 **וירדפו מצרים**. הגם שאמר הכתוב ויהי הענן וגו', זה היה בלילה ובאור בוקר לא עבות חזרו המערכות לדאשונות וראו המצריים הליכת ישראל ורדפו אחריהם:
@30 **ויהי באשמורת הבוקר**. צריך לדעת למה עשה ה' המשפט הגדול הזה בבוקר ולא בלילה שהוא זמן תגבורת הדינים. וראיתי שאמרו ז''ל (ילקוט רל''ה) כי גבריאל טען טענה זו לפני ה' והשיבו אל עליון המתן עד אותה שעה שפעל אביהם עמי שנאמר וישכם אברהם בבוקר עד כאן. פירוש תשובת ה' כי הגם שאינו זמן הנקמה אני מהפך הסדר לבני אברהם כשם שהפך אברהם טבעו הרחמן ומה גם על בנו ידידו ואעשה כן גם אני שהפך הזמן לאשר יחפוץ, ויש בזה הנאה לישראל שיעמוד זכות העת. גם יעשה ה' דברו הטוב בכבודו ובעצמו כמו שעשה אברהם וחבש חמורו בעצמו, והוא אומרו **וישקף ה'**:
@32 **נטה את ידך וגו' וישובו וגו'**. צריך לדעת לאיזה ענין הוצרך לנטות ידו על השבת המים הלא הם מעצמם לא יתמידו לעשות כן ובגמר עליית ישראל שהוא גם כן גמר ירידת אחרון של המצריים (שמות רבה פכ''ב) מעצמו ישוב הים. ואולי כי מהטעם עצמו שנשאר חלוק גם במקומות שעברו בו כבר ישראל והיו המצריים באים שמה חשב הים כי מה אלו אף אלו, וה' גזר כן כדי שיכנסו כולן יחד לתוך הים, וטעם זה לא גודע לים ולא הרהר אחר רבו, לזה צוה ה' למשה לרמוז לים כי כלתה שליחותו וילך כמנהגו:
@32 **עוד** יתבאר על דרך אומרם ז''ל במסכת יום טוב (ה'.) כל דבר שבמנין צריך מנין אחר להתירו והוכיחו כן ממה שאמר הכתוב (דברים ה כז) שובו לכם לאהליכם הגם שאין טעם לאסור עוד אף על פי כן הוצרך להתיר:
@32 **עוד** טעם הנטיה לפי שזולת זה הגם שישוב הים ישוב לאט לאט לצד היותו תש כח מההשתנות שעברה עליו ובזה יוכלו להמלט, לזה צוה ה' למשה להעיר לים בנטית ידו לשוב לתוקפו הראשון תיכף ומיד, וכן הוא אומר **וישב** וגו' **לאיתנו**. או אפשר כי לצד שהוכה הים על ידי משה חפץ ה' שעל ידי משה שב ורפא לו על ידי נטית ידו וה' סומכה כאומרו (ישעי' ס''ג) מוליך לימין משה זרוע תפארתו יתברך:
@32 **עוד** ירצה בנטית ידו לרמוז לים שיעשה מלאכתו בהם שלמה לבל ימלט סוס ורוכבו ולא ימנע מהם בשום אופן לבל ימלט מצרי לשוב עלות מהים וכגון אותם שבקצוי הים שבשיטה אחת יפנו מהים, הרשהו לים על כולם לבלתי ימלט מהם עד אחד וכן הוא אומר **וישובו המים ויכסו** וגו':
@33 **לאיתנו**. רז''ל אמרו (שמות רבה פכ''א) לתנאו הראשון. וקשה לי לדבריהם אין זה מקום התנאי אלא בשעת החלוקה שם יזכיר תנאי זה. ואולי כי יודיע הכתוב כי אחר ששב אז ידע שהוא תנאי שהתנה עמו ה' ולא גזירת כליונו או הגעת צביונו להבטל מהעולם, והגם כי התנאי היה ידוע לו, אולי שלראות הפלאת הדבר שנתיבש ונעשו המים יבשה וגם המים העומדים נעשו חומות אבנים יאמרו כי בא עד קיצו גם כן וכשחזר ידע כי אין זה אלא תנאי ראשון לבד. וצריך לדעת אופן התנאי אם היה ליוצאי מצרים אם כן למה נדעש בפעם הזאת כמאמרם ז''ל (שם) שהתריס כנגד משה ואמר לו אין אני נקרע מפניך שאני נבראתי ביום ג' ואתה נבראת ביום ששי וכו' עד שנטה ה' ימינו לימין משה דכתיב (ישעי' ס''ג ז') מוליך לימין משה. ועוד רואני כי ליחידי סגולה היה נקרע בעל כרחו כמעשה הובא בחולין (ז.) ברבי פינחם בן יאיר וכו' ואם לא התנה עמו אלא ליוצאי מצרים לבד מה כוחו של ר''פ בן יאיר עליו השלום להתגבר על מעשה בראשית:
@33 **אכן** תנאי זה הוא בכלל התנאים שהתנה ה' על כל מעשה בראשית להיות כפופים לתורה ועמליה ולעשות כל אשר יגזרו עליהם וממשלתם עליהם כממשלת הבורא ברוך הוא, ולזה תמצא כמו כן בשמים ובארץ ובכוכבים ובשמש וירח שלטו עליהם הצדיקים יחידים ואין צריך לומר מרובים כאשר חקק ה' להם בעת הבריאה, והוא סוד אומרו (ישעי' מ''ג) בוראך יעקב וגו' ואמרו ז''ל (ויקרא רבה פל''ו) שאמר הקדוש ברוך הוא לעולמו מי בראך מי יצרך ישראל והכל בכח התורה. וצא ולמד מ''ש בפסוק בראשית. והנה ביציאת ישראל ממצרים עדיין לא קבלו התורה ואין גזירתו על הנבראים גזירה ולזה לא הסכים הים ליחלק להם וטען למשה אתה נבראת בששי ואני בג' זה רמז כי אינו בן תורה שאם היה בן תורה הנה הוא קודם לו כי התורה קדמה לעולם כולו, ולזה נתחכם ה' והוליך ימינו לימין משה פירוש הראהו כי הוא בן תורה המתיחס לה ימין דכתיב (דברים לג ב) מימינו וגו' וכשראהו תיכף ומיד נקרע כתנאי הראשון, ולזה כל צדיק וצדיק שיעמוד אחר קבלת התורה יביא בידו שטר חוב א' לכופו ליחלק לפניו, ותמצא שכשלא רצה ליחלק לר' פנחס בן יאיר ולהמתלוה עמו רצה לקונסו ופחד הים ממנו:
@33 **ומצרים נסים וגו'**. פירוש שהגם שהיו נסים ממנו כשראוהו ששב לאיתנו אף על פי כן לקראתו פירוש היה הים בא להם למול מקום שנסים שמה ולכל מקום שהיו נסים היו מוצאים עצמן שהולכים לקראתו, על דרך אומרם ז''ל (סנהדרין ק''י, במדבר רבה פי''ח) בבליעת קרח ועדתו שהיה פה הארץ רץ אחריהם למקום שיעמדו שמה כי כל הנבראים עושים רצון קונם בזריזות וזהירות גדולה, ושיעור הכתוב כי נתגבר הים לאיתנו פירוש לתוקפו ונעשה כנזכר:
@33 **וינער ה'**. פירוש לצד שיש בני אדם בקיאין לשוט בים הגם שיהיה הים בכל תוקפו וגבורתו יתחכמו לשום בו דרך, לזה אמר הכתוב כנגד אלו וינער וגו' בטל מהם הכח ההוא. ולדברי רבותינו ז''ל (שמות רבה פכ''א) שאמרו כי מצרים מת הוא שר של מצרים אמר כי הגשימו והשליט עליו גשם המים ונערו בתוך וגו':
@34 **לכל חיל פרעה וגו'**. פירוש הרכב והפרשים שלא היה בהם כח למהר לבא לתוך הים והיו באים אחריהם שבו המים עליהם למקום שהיו שם לא נשאר בהם וגו':
@35 **ובני ישראל הלכו וגו'**. טעם הודעת דבר זה פעם ב'. אולי כי יכוין לומר שידעו המצריים את הדבר הזה כי ישראל עברו ביבשה והמים היו להם חומה וגו' והם ירדו תחתיות ארץ ובזה ידעו ה' כמאמרו יתברך (פסוק י''ח) וידעו מצרים וגו' וזולת זה לא ירגישו בדבר. וצא ולמד (אבן עזרא פ' כ''ז) ממה שטעו מהמשוגעים ואמרו כי משה היה יודע שעות שבו יתמעט הים וכו' והעביר ישראל באותו עת והמצרים לא ידעו ונטבעו, ומופת זה יסיר שגעון דעת זו כי הלכו ביבשה והמים חומה ב' סימנים אלו יעקרו הכחשת הנס, והראם ה' לנטבעים:
@36 **ביום ההוא**. פירוש **ביום ההוא** היתה התשועה ולא קודם הגם שיצאו ממצרים לא היו בוטחים בעצמן מהם:
@36 **וירא וגו' מת על שפת הים**. קשה למה הוצרך להודיענו שראהו מת פשיטא שלא יהיו חיים אחר הטביעה. ורבותינו ז''ל (מכילתא) אמרו כי ראו במיתתן, והודיענו בזה כי שם גמרו מיתתם, והטעם כדי שיכירו בהם ישראל בעודם חיים והם יראו בישראל ותכסם בושה, ולפי זה תהיה כוונת הכתוב על זה הדרך **וירא ישראל את מצרים** שהיתה יוצאה נשמתו **על שפת הים**, ותיבת מת נקשרת עם אומרו על שפת הים ולא עם תיבת וירא:
@37 **וייראו העם את ה'**. פי' יראת הרוממות, אבל יראת העונש מן הסתם היתה להם קודם במצרים. ולפי מה שהוכחנו בפרשת (י''ב מ''ג) זאת חקת הפסח כי לא קבלו עליהם מצות המלך אם כן אפילו יראת העונש לא היתה להם עד שראו היד הגדולה וייראו וגו', ועל כל פנים ביראת הרוממות הכתוב מדבר מאומרו וירא ישראל את היד הגדולה וייראו וגו'. ואומרו **ויאמינו** כי זה תשלום האמונה בהם:
@38 **אז ישיר**. לא היה צריך לומר אז אלא וישר משה וגו' והדבר מובן כי אז שוררו. אכן יכוין הכתוב להודיענו הכנת המושג. כי כשנכנסה בלבם יראת הרוממות והאמונה השלימה אז זכו לומר שירה ברוח הקודש. ואומרו **ישיר** לשון עתיד לצד שאמר אז חש הכתוב שיטעה אדם ויאמר כי אז מיעט שאין שירה זו יכולה ליאמר זולת אז תלמוד לומר ישיר שישנה לשירה זו גם לעתיד וכל הבא לשיר שירה זו לפני ה' יש לאל ידו. או ירמוז למצוה שמצוה לאומרה תמיד וקבעוה בתפלת שחרית בכל יום:
@38 **ויאמרו לאמר אשירה**. פירוש אמרו זה לזה **לאמר** פירוש שיאמרו שירה יחד בלא בחינת השתנות והפרדה עד שיהיו כאיש אחד, הגם היותם רבים, ונתכוונו יחד ועשו כן ואמרו **אשירה** לשון יחיד כאילו הם איש אחד שזולת זה היו אומרים נשירה:
@38 **כי גאה גאה וגו'**. אין לשבח תחלה אלא על מפלתן של רשעים על דרך אומרו (משלי יא) ובאבוד רשעים רנה, ופירוש אומרו **גאה גאה** יכוין על פרעה שנתגאה גאות ששמה גאות כי דרך הגאים יתגאו על כיוצא בהם אדם על אדם כיוצא בו וגאותו של זה אינה חשובה גאות כי הוא מתגאה על השפל אבל פרעה גאה גאה פירוש גאות שנקדאת כפי האמת גאות גאה כי לא החשיב מאמר עליון ואמר מי ה'. או ירצה **גאה גאה** שהיתה גאותו כפולה, סוס ורוכבו של הגאה רמה וגו':
@38 **עוד** ירצה **גאה גאה** על ה' מלך גאות לבש ונתכוונו לומר כי קודם שעשה משפט זה היתה לו בחינת גאוה אחת ובאמצעות יד הגדולה גאה גאה. גם לרמוז בין בעליונים בין בתחתונים באמצעות דבר זה. ולדרך זה חסר הנסמך לרוכבו. ואולי שיעור הכתוב הוא על זה הדרך אשירה לה' כי גאה גאה פירוש ה' ונמשכת עוד תיבת כי גאה גאה למטה על זה הדרך ולאותו שגאה גאה סוס וגו' רמה בים:
@39 **עזי וזמרת וגו'**. הנה סדר העומדים לפני ה' לשורר ולשבח ולהתפלל הוא להתחיל בדברים המושכלים מה' אליו ואחר כך במושכל מה' לאבותיו, וכמו שמצינו שתקנו אנשי כנה''ג באבות אלהינו ואחר כך אלהי אבותינו, ולזה סדרו בהתחלת השיר מה שהגיעם מטובו ואמרו עזי וזמרת יה ויהי לי לישועה, והוא מה שנתחסד ה' עמהם להושיעם מהצרה שהיו בה קודם שיגיע הקץ, וזה היה לצד רחמיו אליהם, וכמו שכתבתי ענין זה באורך בפ' שמות (ג' ז'), ובפ' וארא (ו' ג'), ולזה גמרו אומר **זה אלי** ואחר כך אמרו **אלהי אבי**, והוא כסדר עצמו של כנסת הגדולה שקבעו לומר אלהינו ואלהי אבותינו, וכאן אמרו לשון יחיד כי נעשו כולם כאיש אחד כמו שפירשתי בפסוק ויאמרו לאמר:
@40 **ה' איש מלחמה**. פירוש גם במדת הרחמים עשה מלחמה, ולא שישתנה מפני זה חם ושלום אלא ה' שמו, על דרך (מלאכי ג) אני ה' לא שניתי. או ירצה כי בזמן עצמו שעשה מלחמה עם המצריים בזמן עצמו היה מתנהג במדת הרחמים עם ישראל וכמו שפירשתי במאמרו יתברך (לעיל ו' ב') וידבר אלהים אל משה וגו' אני ה':
@42 **תהומות וגו'**. לפי מה שפירשתי לעיל (י''ד כ''א) כי חצי הים נקפא וחצי נבקע, וכל חלק יקרא תהום לצד הפלגת ריבויו ושניהם יכסיומו, ועיין בפסוק קפאו תהומות באופן אחר:
@42 **ירדו במצולות**. ירמוז אל אותם שהיו משתדלים לעלות מהים בכח מלאכת השיטה שהורידם לעמקי מים וכמו שפירשתי בפסוק (שם כ''ז) וינער וגו':
@43 **ימינך ה' וגו** '. פירוש כשתהיה מדת הרחמים מתחזקת לעשות דבר משפט והוא אומרו **נאדרי בכח** אז ימינך ה' שהיא מדת הרחמים עצמה תרעץ אויב. או ידרוש מסופו לראשו אימתי ימינך ה' נאדרי בכח כשימינך ה' תרעץ אויב אז תפול אימתה ופחד על כל הנבראים מפני שמך האדיר:
@44 **וברוב גאונך**. פירוש לצד שהזכיר כי ירעוץ קמיו הוסיף לומר כי עוד להם שיהרסם ברוב גאונו, והכוונה שלא יהרסם הריסה קלה בלא הרעשה אלא במופתים ובאותות יעשה בהם משפט כתוב. ואומרו **תשלח חרונך יאכלמו כקש** פירוש לא שאתה צריך לרוב גאונך להרום אותם אלא הגם שיכול אתה לשלח חרון אחד שלך ויהיה נאבד כקש:
@45 **נערמו וגו' נצבו וגו' קפאו וגו'**. פירוש כנגד ג' מלאכות שעשה ה' בים. הא' שנבקעו ונתקבצו כולם יחד ולא נשארו מפוזרים במקום הפנוי אלא נעשו כולן ערימה אחת לעשות מדרך רגלי ישראל. ב' המימות שהיו מתקבצים ובאים ושופכים בים מהצדדין היו נצבים במקום שנערמו הראשונים והוא אומרו **נצבו כמו נד נוזלים**. פירוש אותם שנוזלים ובאים נצבו כמו נד. ג' לפי מה שהעלינו (לעיל י''ד כ''א) כי לא נחלק כל הים כדי שלא יצטרכו לרדת לעמקי הים חלק שלא נחלק נקפא ונעשה כיבשה וכנגד זה אמר קפאו וגו'. וכבר כתבתי כי ההקפאה קדמה לביקוע. והוא אומרו **קפאו תהומות בלב ים** קודם שנקרע קפא לבו ונשאר מלבו ומעלה מים שלא קפאו ונבקעו. וטעם אומרו **תהומות** לשון רבים, לדבריהם ז''ל (שמות רבה פכ''ד) שאמרו שהים נקרע לי''ב קרעים וכל מקום ומקום שנקרע קפא שם התהום וכנגד כולם אמר **תהומות**:
@46 **אמר אויב וגו'**. טעם לחזרת דברים אלו והם עצמן שאמרו בתחלת השירה מרכבות פרעה וחילו ירה בים וגו'. נתכוונו לשורר על אופן סדר המעשה שנתחכם ה' עשות במלאכת הים לישראל לנם וצוה ה' שיעמוד הנם כשורתו וכמנהגו לאויב שבזה טעה וחשב לרדוף כי ישיג ויחלק שלל שזולת זה לא היה רודף דרך ים ולא היו מובטחים ממנו:
@46 **אחלק שלל**. הנה הרשע חשב עשות ג' דברים. א' שוה בכולן והוא לשלול כל שללם, והוא אומרו אחלק שלל, ב' שיקח אותם לעבדים כבראשונה, והוא אומרו **תמלאמו נפשי** פי' תתמלא נפשי מהם כשאחזור לכבוש אותם לעבדים. גם רמז שיוסיף לעשות בהם חפצו בעינוי יותר ממה שעבר. ג' להרוג משה ואהרן וזקניהם וגדוליהם, והוא אומרו **אריק חרבי** וגו' ואומרו **תורישמו ידי** ירצה על דרך אומרם ז''ל (שמות דבה פ''א) בפסוק (ב' ט''ו) ויבקש להרוג את משה שבקש להורגו בסייף ולא שלטה בו וכו', והוא שאמר משה (לקמן י''ח ד') ויצילני מחרב פרעה לזה אמר אויב תורישמו ידי כי תשיג ידו מה שלא השיג מקודם:
@47 **נשפת ברוחך וגו'**. ג' פורעניות כנגד ג' מחשבות, כנגד מה שאמר אחלק שלל כסמו ים בזה הגם שימלטנו סום וישוט בים הנה שללו אבד, וכנגד העינוי שחשב על היהודים כרמוז באומרו תמלאמו נפשי גם מה שחשב להריק חרבו אמר **צללו** וגו' פירוש מתו, ולא מתו תכף ומיד אלא צללו כעופרת במים אדירים ואמרו ז''ל (מכילתא) שהיו המים מעלים אותם עד לשמים ומורידים אותם עד התהום והיו מתים באריכות זמן, והוא אומרו **כעופרת במים אדירים** יכוין לב' דברים, הא' הוא השקיעות, והוא אומרו צללו כעופרת, והב' הוא מניעתם מלמות תכף ומיד, והוא אומרו במים אדירים והם יעלום ממעל וימנעום ממות תכף ומיד שיר ושבח לאלהים על נסיו ומופתיו:
@48 **מי כמוכה באלים וגו'**. פירוש כיון שאנו רואים מצרים שהוא השר מצרים שמו מת מי ידמה לה' בבני אלים:
@48 **עוד** נראה על דרך אומרם ז''ל (חגיגה ט''ז) מלך בשר ודם כשנחבא בתוך העם אינו ניכר כי הוא זה מה שאין כן אלהינו אות הוא בצבאו, והוא אומרו **מי כמוכה** אפילו כשאתה באלים בלא שום היכר המלוכה רשום הוא:
@48 **עוד** ירצה על דרך אומרם ז''ל (מכילתא) מלך בשר ודם מוראו על הרחוקים יותר מהקרובים אבל הקב''ה מוראו על הקרובים יותר וכו', והוא אומרו **מי כמוכה באלים** כי שם מכירים יותר אבל בתחתונים אימתי מי כמוכה כשאתה נאדר בקודש כשאתה נותן חוזק ואדר לבחינת הקדושה כמעשה ארץ מצרים אשר השפיל גאון רשע והאדיר הקדושה:
@48 **עוד** ירצה על דרך אומרו נהר דינור נגד ונפיק מן קדמוהי, (דניאל ד' י'), ואמרו ז''ל (חגיגה י''ג:) כי מזיעת החיות שמזיעים בעת שאומרים קדוש יוצא נהר דינור, והוא אומרו **נאדר בקודש** פירוש כשמאדרים אותו בקודש אז לצד המורא שנכנם בחיות כשמהללים אותו עושה הנוראות ההוא שמזיעים נהר דינור:
@48 **נורא תהלות עושה וגו'**. פירוש יש לכל לירא מהגיד תהלותיו לצד שמעשיו כולם פלא ומי הוא שיצטדק בתהלותיו, כי אין אדם ישיג דעת המופלא לשבח בו ואיך יהללו במדרגה קטנה כיון שיש לו בחינה מופלאת ומכוסת גדולה ועצומה:
@49 **נטית ימינך וגו'**. רבותינו ז''ל אמרו בספרא (מכילתא) מלמד שהיה הים זורקן ליבשה והיבשה לים אמרה היבשה לים ומה במקום שלא קבלתי אלא דמו של הבל יחיד נאמר לי ארורה וגו' עתה איך אוכל לקבל כל האוכלוסים עד שנשבע לה הקב''ה שאינו מעמידה בדין דכתיב נטית ימינך וגו' עד כאן. וכן תרגם יונתן בן עוזיאל, מכאן אתה רואה כי לא רצה הים לקבלן והיה פולטן ליבשה, ולא כן מצינו שאמרו בפסחים קי''ח וזה לשונם אמר הקב''ה לשרו של ים פלוט אותם ליבשה אמר לפניו רבונו של עולם יש עבד שנותן לו רבו מתנה וחוזר ונוטלה ממנו אמר לו אתן לך א' ומחצה וכו' אמר לו יש עבד שתובע רבו אמר לו נחל קישון יהיה ערב מיד פלטן ליבשה ובאו ישראל וראו אותם שנאמר וירא ישראל וגו' עד כאן. הדי שאמרו ז''ל בפירוש שלא היה הים חפץ לפולטן אם כן אחר כך כשהחזירתם לו האדמה למה לא שמח לקבלם, גם למה הוצרך ה' לפרוע לו ממחנה סיסרא והרי שלך לפניך יחזירם לו בעצמן ולא היה צריך ערב:
@49 **עוד** קשה הלא עינינו רואות כי אין הים סובל בתוכו אדם ובהמה אלא פולטן ליבשה שזכורני פעמים שטבעו בני ארם בים והשליכן ליבשה מהם ביום ההוא מהם אחר יום או יומים ולדבריהם ז''ל הים חפץ שיהיו עומדים אצלו. וראיתי לרש''י ורשב''ם שפירשו שטענת הים הוא לצד פרנסת דגי הים שימצאו מזון. וצריך לדעת אם כן למה לא קבלם כשזרקתן היבשה והיו למזון הדגים. והיה נראה ליישב כי אז היו סרוחים ואינם ראוים למאכל דגים, וזה דברי דיחוי כי מן הסתם לא יתעכב ה' לומר ליבשה לקוברם מדין לא תלין, וגם אין צורך בדבר לעכב קלונם על פני האדמה אלא עד שימותו ואחר מיתה מה צורך להתעכב בלא קבורה. והגם שאין דרכנו בחיבור זה לפרש מאמרי רבותינו ז''ל, עם כל זה הענין הוא צורך משמעות הכתוב, וכדי שלא נאמר מדרשים חלוקים נראה להתאימם על פי מאמרם ז''ל (מכילתא י''ד ל') וכתבנו אותו בפסוק וירא ישראל וגו' מת על שפת הים כי ראו אותם בגמר מיתה בעודם קצת חיים כדי שיכירו ואז וכו', ולפי דבריהם אלו זרח אור ב' המאמרים, כי מה ששאל הים שלא יפלוט אותם הוא לצד כי ה' אמר אליו לפלוט אותם חיים לסיבת הנזכר לשמח ידידיו שיכירו המצריים ישראל ויראו ותכסם בושה כאמור בדבריהם הפלגת נם זה, והגם שלא רמוז במאמרם זה ענין הפליטה שתהיה בעודם חיים, אף על פי כן רבותינו ז''ל סומכים למה שידוע ביניהם, ולזה טען הים יש עבד שנותן וכו' הכוונה כי חפץ הוא לגמור המצוה במכעיסי אל. ותמצא כי כל שרי מעלה וכל ברואי מעלה ומטה חפצים וחשקים לעשות מצות ה' כי הם אביונים בדבר לצד שאין להם מצות, וכן תמצא שם בפסחים באותה סוגיה כי גבריאל בקש מה' להציל אברהם מכבשן האש ואמרו שם כי ה' לא קפח שכרו ואמר לו תזכה ותציל ג' מבני בניו וגו' עד כאן הרי כי זכות הוא למלאכים לעשות חסד לצדיקים ולאוהבי עליון, וכמו כן היה חפץ הים שתגמור יציאת נפשם בים ולא ביבשה ולזה צעק לבו, והשיבו אל עליון כדרך שעשה לגבריאל כי לעתיד ימציא לו זכות אחר לאבד עם רשע חלק ומחצה והוא מחנה סיסרא שהוא יעשה בהם מצות איבוד רשעים:
@49 **עוד** יש טעם בטענת הים שהיה חפץ שתגמר מיתתם בים לקחת כל כוחות החיוניות שהם כל הנפשות של העם, כי מטבע נפשות העמים לעמוד במקום מיתתן כאומרו (קהלת ג') ורוח הבהמה היורדת היא למטה לארץ, והעובדי כוכבים ומזלות נמשלו לבהמות וכי תצא נפשם בים יזכה השר בהם לבחינת המושגות אצלו מהענין, ולזה כשאמר אליו לפולטן חיים שאז תהיה הארץ זוכה בדבר כי קונים מקומן במקום הנחתם יורדים שמה צעק לבו יש עבד וכו' עד שענהו רבו כי יתן לו בעדם וכו' פירוש בני אדם חיים כמות אלו ופרט לו בדומין לאלו ושאב חיותם מהם שהוא עיקר חשקו לא בגוף, ולזה אחר שפלטם ויצתה נפשם על שפת הים וזרקתם האדמה לים לא רצה לקבלם כי אינו מטבעו והארץ היא המכסת על בניה אשר לוקחו ממנה והכריחה ה' לקבלם כי לה נוגע הדבר. ולא תקשה לדרכינו זה ממה שאמרו שם בפסחים כי כשפרע ה' לים פתחו דגים שבים ואמרו ואמת ה' לעולם ע''כ, אם כן להם נוגע הדבר, ואולי כי בעת אשר יחפוץ הים בקבלתם בתוכו שהוא בזמן שהם חיים היו הדגים נהנים מהם ביני וביני קודם שימותו ואז ישליכם הים ואין להם עוד מהם מזון ועל זמן פרנסתם אמרו שירה. וראיתי מי שנתעצם בטענת הים יש עבד וכו' הלא יד עבד כיד רבו, ואין בזה קיהוי כי הים טענתו נכונה על דרך אומרם (תענית כ''ה,) משמים מיהב יהבי משקל לא שקלי, ועל אדנות אדונו הוא אומר וכי קרה מקרה זה לאיזה עבד מעבדי ה' שנתן לו רבו וחזר וכו', ולזה לא אמר יש אדון שנותן וכו' וחוזר וכו' כי זו אינה טענה יש ויש ואדרבא יד עבד כיד רבו וכאלו לא נתן אלא דבריו הם לרבו כי אינו מתנהג כן עם עבדיו:
@52 **אז נבהלו וגו** '. אומרו אז לומר כי אינו בזמן שדבר בו עד עתה שהוא זמן של הנכנסים לארץ אלא על זמן ביאת גואלנו, ולזה אמר אז נבהלו אלופי אדום, וכן הוא אומר (במדבר כ''ד י''ח) והיה אדום ירשה, וגם אז יחול זמן לזכות במואב ועמון, ולזה אמר **אילי מואב יאחזמו רעד**, וטעם שלא הזכיר עמון, כי גם הוא מאב פירוש עם בתו בא, ואז גם כן נזכה בכל הנשאר מהכנעני, והוא אומרו נמוגו כל יושבי כנען, ואמר **יושבי**, לומר שיטהרו בהם אפילו שאר העמים, וטעם אומרו לשון עבר כי דבר ה' כאילו נתקיים והיה:
@53 **תפול וגו' עד וגו'**. פסוק זה ושלאחריו ידבר כל אחד על ב' הכנסות לארץ אחת בימי משה ואחת בימי המשיח, ולזה אמר העניינים כפולים:
@55 ה' **ימלוך וגו'**. טעם שלא אמרו ה' מלך, אמרו הם עצמם הטעם כי בא וגו' פירוש לצד שלא נעשה המשפט אלא באומה אחת, והוא אומרו **כי בא סוס פרעה** וגו' כי לא יוקח מזה הכחשת כל האלהות אשר אומות אותם יעבדו ולזה אין מלכותו נכרת לעולם, מה שאין כן לעתיד לבא כי יעשה ה' משפט בכל הגוים אז יהיה ה' למלך על כל הארץ והוא אומרו ה' ימלוך:
@55 **או** ירצה טעם אומרו **ימלוך** ולא מלך כי בא סוס פרעה וגו' פירוש כולם היו בטביעה כסוס אחד והכוונה בזה כי לא נמלט מהם עד אחד כשם שיטבע אדם אחד יטבעו כולם, והן אמת אם היה מגיד לעולם הפלגת ועוצם הנם להכיר העולם גדולת תגבורת פאר נצחון והוד יסוד אמונתינו אשר כל שומעיו יתלהבו ויאמרו הבו יקר כי הוא זה אדונינו מלכנו ומעתה יהיה ה' למלך אלא שלא הלכו ביבשה ונמלטו זולת בני ישראל, והוא אומרו ובני ישראל הלכו וגו' ולהם לא ישמעו האומות כי הם נוגעים בדבר להיותו אלהיהם:
@59 **ויסע משה וגו'**. פירוש נסיעה זו על פי משה נסעוה ומכאן ואילך על פי ה':
@60 **ויבואו מרתה וגו'**. צריך לדעת למה לפעמים יקרא לה מרתה ולפעמים מרה, ונראה כי שם המקום היה מרתה והמעיין של מים שבו לא היה לו שם מיוחד, ואמר **ולא יכלו לשתות מים ממרה** פירוש מהמעין שהיה במרתה מטעם כי מרים הם, ואחר כך חזר הכתוב לגלות לך כי שם מרה שאמר הוא שם שנקבע למעין ההוא אחר שמצאו מימיו מרים קראו הכתוב על שם העתיד, ולדרך זה יבא על נכון אומרו **כי מרים הם**, לצד שקריאת שם מרה הוא על העתיד ואז עדיין לא נקרא שמה מרה וכאלו אמר לשתות מים ממרתה, לזה הוצרך לומר **כי מרים הם** והבן:
@61 **וילונו וגו' לאמר**. יספר הכתוב בגנותם כי באו בריב, ואין הכתוב מקפיד אלא על תלונותם, אבל על פרט אומרם מה נשתה לא יקפיד ה' אם היו אומרים כדרך שואל חסרונו:
@63 **אם שמוע וגו'**. פירוש **אם שמוע** לחק ומשפט אשר שם כאמור בסמוך תזכו לשמוע בקול ה' פירוש ממנו יתברך, על דרך אומרו (דברים ד' ל''ג) השמע עם קול אלהים וגו', ומבשרם שיזכו למה שזכו אחר כך, וה' נתן להם שבת ודינים קודם (סנהדרין נ''ו:) לנסותם אם ישמעו למצות אלו יצום התורה כולה, והוא אומרו למעלה **ושם נסהו** פירוש אם יעמוד בקבלת התורה. ותמצא שכאן רמז הכתוב ד' מצות ללמוד וללמד לשמור ולעשות, כנגד ללמוד אמר אם שמוע וגו' בקול ה' זו תלמוד תורה, וכפל השמיעה לטעם הנזכר, גם לרמוז להם שיהיה עסק התורה בחשק גדול שהגם שעודנו לומד יתאוה ללמוד עוד וזה יגיד שאינו שבע וקץ בלימודו. וכנגד ללמד אמר **והישר בעיניו תעשה** על דרך אומרם ז''ל (נדרים ל''ז.) מה אני בחנם אף אתה בחנם, ושיעור הדברים הוא על זה הדרך והישר בעיניו יתברך לעשות הוא עם ברואיו שנתן להם התורה בחנם תעשה גם כן אתה, וכנגד מצות עשה אמר **והאזנת למצותיו**, וכנגד מצות לא תעשה אמר **ושמרת כל חוקיו** לשון שמירה הצודקת על ל''ת:
@63 **אשר שמתי וגו'**. טעם שפרט לומר אשר וגו' נתכוון לבל יאמרו כי אינו מבטיח אלא שלא להביא עליהם מחלה אבל אם באה לזולת בהדי הוצא לקי כרבא ואין כאן הבטחה לזה אמר אשר שמתי במצרים, ולכו וראו מעשה מצרים שהגם שהביא ה' כמה מחלות היה ה' מגביל למכה לבל תגע בהם הא למדת שאפילו בשעת חרון אף יפליא ה' להם חסדו ויצילם ה':
@63 **כי אני ה' רופאך**. פירוש לצד חולאים שאינם בידי שמים כאומרם ז''ל (כתובות ל'.) הכל בידי שמים חוץ מצינים ופחים. לזה אמר **כי אני ה' רופאך** פירוש הגם שיקר לך מקרה מהם אני ארפאך מהם, כי משה הוא שנתחכם להביאם דרך זה לסיבה ידועה:
@67 **ביד ה' בארץ מצרים**. פירוש כי אם היו במצרים והיו ממאנים לצאת מה היה הדבר היו מתים הרוגי ה', לזה אמרו כי הם בוחרים שהיה ה' ממיתם בארץ מצרים על מיאונם ולא יודו לצאת, וימותו ברעב, על דרך אומרו (איכה ד') טובים היו חללי חרב מחללי רעב:
@67 **בשבתנו על סיר וגו'**. מכאן אתה למד כי מדברי לשון הרע זה הם אותם שלא היו עליהם עול סבלות מצרים והם השוטרים, כי המעונים סובלי עול הגלות לחמא עניא אכלו במצרים. ואולי שהם הרשומים ברשע הוא דתן ואבירם:
@67 **בשבתנו על וגו'**. פירוש ובאמצעות הבשר היו אוכלים לחם לשובע כי היה להם הבשר ללפת בו את הפת:
@67 **או** ירצה כי מלבד שכבר אכלו לחם פירוש סעודתם היו מוסיפין לאכול בשר על השובע. ואולי שדקדקו באומרם **על סיר** וגו' ולא אמרו באכלנו בשר וגו' לרמוז כי לא היו אוכלים שנתבשל ושהה כי זה יפגם טעמו אלא שהיו יושבים על הסיר לאוכלו בעת גמר בשולו. ורמזו לו בדבריהם כי הגם שיאמר להם שחטו ממקניכם ואכלו בשר זה לא יספיק בתמידות כאשר היו רגילים לאכול תמיד לחם ובשר. עוד יתבאר הכתוב למה שקדם לומר כל עדת בני ישראל מן הסתם לא תהיה כל העדה בגדר שוה בתלונתם נגד ה' ונגד נביאו, ולזה רשם ה' ב' טענות כנגד ב' כתות שהיו בישראל אחת תובעת בשר ואחת תובעת לחם, והוא אומרו **בשבתנו על סיר הבשר** זו כת הפריצים שבהם והתחיל הכתוב בדברים אלו כי בקלקלה מתחילין מן הצד, ואחר כך אמר באכלנו לחם לשובע כנגד התובעים לחם לאכול כי היו רואים עצמן בארץ לא עבר בה איש ולא היו מושלים ברוחם להמתין עד שיתן להם רבם מנתם:
@68 **ויאמר ה' אל משה הנני וגו'**. לא אמר הכתוב לאמר. גם התחיל לדבר נוכח וסיים נסתר ויצא העם וגו'. יתבאר על דרך אומרם ז''ל (יומא ע''ה.) כי המן היה יורד לצדיקים פתח אהלו של כל אחד ולא היה צריך לצאת אחריו ולשאר העם היה יורד במקום אחר והיו יוצאים ללקוט, והוא אומרו **הנני ממטיר לכם לחם** וגו' פירוש באין צורך לצאת ללקוט, אבל העם יצאו וילקטו. כנגד מה שלא בטחו וקדמו לשאול ישיגוהו בטורח:
@68 **וטעם** שלא אמר בתחלת נבואה זו לאמר, לצד כי עדיין יצוהו פעם ב' כל הדברים בפרשה שאחר זו אלא שהקדים הדברים למשה למצוא בפיו מענה, ותכף ומיד השיבם שהנבואה נאמרה לו כהרף עין ותכף ומיד והנה כבוד ה':
@68 **למען אנסנו וגו'**. כי לחם מן השמים לא יצטרך שום תיקון ובזה יהיו פנוים מכל ואראה הילך וגו':
@68 **עוד** ירצה על זה הדרך טעם **דבר יום ביומו למען אנסנו** כשיהיה צריך לו בכל יום למזונותיו:
@69 **והכינו את אשר יביאו**. פירוש כי ההבאה עצמה בכלל ההכנה וצריכין להכינה מיום ו' כדי שלא יביאו בשבת, והוא מאמר משה לישראל (פסוק כ''ט) אל יצא איש ממקומו וגו':
@70 **ערב וידעתם וגו** '. פירוש לצד שישראל דברו בדרך החלטת המניעה שימצאו בשר במדבר באומרם מי יתן מותינו וגו' ולא שאלו הדבר קודם זה יגיד כי היה להם הדבר בלתי אפשר, לזה אמר להם ערב וידעתם כי ה' וגו', כי עד עתם אינכם יודעים המוציא אתכם מה נורא מעשיו ולא לקחתם ידיעה מהמסות הגדולות כי כל יכול עכשיו מחדש תכירוהו. וכונת דבריו הוא לשבט מוסר כי טח מראות עיניהם וגו' (ישעי' מ''ד). וטעם שלא תלה הידיעה אלא במעשה ערב ולא במעשה בוקר, לצד שהוא המופלג אצלם במניעה. ואמר **וידעתם** בתוספת וא''ו, לומר מלבד שתוסר יראת מות ברעב אלא שיהיה בדרך מופלא כמעשה ה' הנורא המוציא אתכם מארץ מצרים:
@71 **ובוקר וראיתם וגו'**. פירוש בוקר הוא מה שאמר בסמוך ויאמר משה וגו' והנה כבוד ה', וענין זה היה ביום ב'. ולפי זה טעם אומרו **וראיתם** בתוס' ו', פירוש מלבד דברו אשר ידבר לכם על ידי עוד יעשה ה' לכם דבד שיראה לכם את כבודו. או ירצה באומרו **ובקר** כי גם בקר ידעו כי ה' וגו', והיא נמשכת למעלה עם אומרו ערב וידעתם וגו' ובקר, ואומרו וראיתם הוא תחלת ענין, וכפי זה אפשר כי בו ביום ראו כבוד ה':
@72 **ויאמר וגו' בתת וגו'**. להיות שבתחלה אמר הדברים סתומים ערב ובקר ולא אמר מה יהיה ערב ובקר לזה חזר ופירש מה שאמר ערב וידעתם הידיעה היא בתת ה':
@73 **ויאמר משה אל אהרן**. פסוק זה אפשר שהיה ביום ראשון עצמו שדבר אליהם ערב וידעתם. או אפשר שהיה למחרתו, ומה שאמר להם ערב וידעתם אינו חוזר על ערב של אותו יום אלא ערב של זמן שיתן ה' להם כאומרו בתת ה' וגו' ולאפוקי בוקר:
@74 **כדבר וגו'**. פירוש שהיה ה' כיושב ומצפה שיפנו אליו ותכף לדברו נראה כבוד ה' בענן:
@75 (יא~יב) **וידבר וגו' לאמר שמעתי וגו' דבר וגו'**. קשה למה אמר תיבת **לאמר** בפסוק א' ולא הספיק במה שאמר אחר כך דבר אל בני ישראל, ואם נתכוין שגם פרט זה שאמר לו שמעתי את תלונות וגו' יאמרנו לישראל אם כן למה הוצרך לומר עוד אחר כך דבר. ונראה לומר על פי דבריהם ז''ל (יומא ד':) שאמרו שכל האומר דבר לחבירו הרי הוא בבל תאמר עד שיאמר לו לאמר, והנה כשדבר ה' למשה ואמר לו **שמעתי** וגו' הם דברי ה' למשה, וענין זה הוא בבל תאמר לזה אמר לו ה' **לאמר**. והנה אין הכרח בזה שחייב לומר אלא רשות הוא שמרשהו לומר לשלול בל תאמר והדבר בידו להודיע דבר ה' זה אליהם, וכשרצה ה' שידבר אליו דברים שנוגעים לישראל אמר דבר אל בני ישראל כי מכאן ואילך הם דברים שאני מחייבך לדברם, ולזה תמצא ששינה ה' את דברו כי מקודם דיבר דרך נסתר על ישראל כאלו מדבר דברים בינו לבין משה אלא שהרשהו לספר לישראל. וכשיאמר לישראל צריך לדבר להם על זה הדרך כי ה' אמר למשה ששמע תלונות בני ישראל לא שהושלח מה' לומר להם משמו ששמע וגו', ומאמר ב' אמר אליו דבר אל בני ישראל משמי בשליחות בין הערבים תאכלו. וטעם שהוצרך לומר תיבת לאמר נתכוון שיאמר להם משמו יתברך. וזה שיעור הכתוב דבר אל בני ישראל שאני אומר להם בערב תאכלו וגו' והוא אומרו **לאמר**, ומשמשת תיבת לאמר במקום כה אמר ה', גם בזה יוצדק גמר הדברים שאמר **אני ה' אלהיכם**, וזולת לאמר ישמע הדבר שחס ושלום על משה:
@79 **ויאמרו איש וגו' מן וגו** '. צריך לדעת מה כוונת הכתוב בזה. ואולי כי בראותם אותו הזמין ה' לפיהם במקום שיאמרו מה הוא אמרו מן הוא, וזה שמו אשר קבע לו ה' ושם שמו בפי ישראל על דרך אומרם ז''ל (ברכות ז':) אשר שם שמות בארץ שיכוונו לשמות אשר קרא להם הבורא. ואומרו **כי לא ידעו** נתן הכתוב טעם המצאת השם לפיהם הוא לצד שלא ידעו מה הוא ומאמצעות זה נפל אליא בפיהם. ואולי כי מזה נתחכמו בני ישראל וקראו שמו מן דכתיב (פסוק ל''א) ויקראו בית ישראל שמו מן שהשכילו בתיבת מן שאינה מן הרגיל בנדבר ואין זה אלא רוח ה' דיבר ומלתו על לשונם כי זה שמו:
@80 **איש לפי אכלו**. פירוש לפי שיעור בני ביתו אם רבים אם מעטים. ואמר **אכלו** כי אכילת כולן תחשב אכילת האיש התלוי בו, והעד על זה מה שאמר אחר כך וימודו בעומר וגו' איש לפי אכלו וגו', וחזר לומר כמה יקחו לכל אחד עומר לגלגולת, וחזר לומר **מספר** וגו' לומר שלא יעשו הפרש בין קטן לגדול אלא מספר הנפשות כי כולם ישוו באכילת המן. ואומרו **לאשר באהלו** נתכוון לומר כי מי שיש לו באהלו איש או אשה שאין מזונותיהם עליו והם בשכונתו שגם להם יקח האיש. ודרשת רבותינו ז''ל (יומא ע''ה.) תאיר עינים בנפלאות ה':
@83 **ויאמר משה וגו'**. אולי כי מצוה זו משה מעצמו דן אותה, להיות שראה כי ה' נותן להם דבר יום ביומו זה יגיד כי אין יום אחד מכין לחברו והבין דבר מתוך דבר ואסר להם. ולזה אמר הכתוב ולא שמעו אל משה, וקשה לא היה צריך לומר אלא ויותירו וגו' ואני יודע שלא שמע ו:
@83 **עוד** למה לא הספיק לומר ולא שמעו ויותירו ואני יודע כי לא שמעו למשמיע. ולדברינו יבא על נכון פירוש **ולא שמעו** למה שנתחכם ואסר להם מדעתו. ולדרך זה ידויק גם כן אומרו במאמר הקודם לזה זה הדבר אשר צוה ה' מה שלא אמר כן במה שלפנינו. וטעם שהבאיש וירם תולעים, שהסכים ה' על ידו שהצדיק בסברתו סברת חכם עדיף מנביא:
@83 **ואפשר** לומר כי לעולם מפי הגבורה נאמרה לו מצוה זו אלא לצד שכבר אמר זה הדבר אשר צוה ה' סמך שכל ענין פרטי דיני המן נמשך למה שהקדים לומר זה הדבר אשר צוה ה', והם לא השכילו כונתו וחשבו כי הוראתו הוראת חכם לא הודעת נביא:
@84 **וירם תולעים וגו'**. טעם שהקדים וירם וגו' לויבאש, לצד שהרמת התולעים תמצא במין המתוק ולא יבאש כי אין הסרחון רגיל בדברים המתוקים כרגילות הויית התולעים ומן זה טעמו כצפיחת בדבש ולזה אמר **וירם תולעים** ולא די זה אלא **ויבאש**. והעד הנאמן לפרושנו זה אומרו (פסוק כ''ד) ולא הבאיש ורמה לא היתה בו פירוש לא מלבד שלא הבאיש אלא אפילו רמה הרגילה להיות בלא סרחון לא היתה בו, ואם לא ירום תולעים עד שכבר הבאיש אחר שאמר הכתוב ולא הבאיש אין צורך לומר עוד ורימה וגו'. והנה ראיתי לרבותינו ז''ל (מכילתא) שלא פירשו כדברינו, ואולי כי יסברו שעל כל פנים הגדלת התולע יקדים לה קצת מההבאשה שממנו תתהוה הגם שלא יבאש המתוק. ובדרך רמז ירצה כי אין תולע גדל אלא מהנבאש. והנה מצינו שתרגם אונקלוס רע ביש, ובחינת הרע ויסודו הוא עבור פי התורה והמצוה, ואדם כי יחטא ירום תולעים, והוא סוד גדילת תולעים מהפירות ואויר האדמה אחר חטא האדם, והוא אומרו **וירם תולעים** הטעם הוא לצד ויבאש שנעשה בו בחינת הרע שהניחוהו הפך מצות התורה, ולזה כשאמר להם משה הניחו אותו וגו' עד הבקר אמר הכתוב ויניחו אותו עד הבקר כאשר צוה משה ולא הבאיש ורימה לא וגו' פירוש לא נגע בו בחינת הרע ובזה ורימה לא היתה, וכמו כן הצדיקים אשר לא יטעימו נפשם מבחינת הרע לא יתליעו. וצא ולמד מעשה ר' אליעזר בר רבי שמעון בן יוחאי עליו השלום (ב''מ פ''ד:) כי תולע אחד לבד גדל באזנו לצד בחינת הרע אשר נגע שם:
@86 **ויגידו למשה וגו'**. מכאן משמע שלא הודיעם קודם דבר ה', וקשה איך יכבוש חס ושלום נבואתו ולימדונו רבותינו (סנהדרין פ''ט.) דין נביא הכובש נבואתו וכו' חס ושלום, ומה גם בהגדת מצוה לקיים ישראל רצון המלך שיש בזה ב' בחינות כובש נבואה ועקירת המצוה, ואין לומר כי חם ושלום שכח מצות ה' אם כן נחוש לו גם כן ששכח ממה שנצטוה ועדיין שכוח חם ושלום, ומה גם שלא היה לו לעכב זמן מה לישכח ותכף ומיד היה לו להגיד נבואתו, וגם קושיא לאלהינו למה לא הזכירו כשידע בו ששכח באותה שעה עצמה היה לו להזכירו ולא היה מניחו שכוח עד ז' ימים שהוזכר מעצמו:
@86 **אכן** משה רבינו טעמו ונימוקו עמו ובמתק לשונו השיב תשובה כראי מוצק (איוב לז) באומרו **הוא אשר דבר ה' שבתון שבת** וגו' כאן בנועם דבריו השמיט תיבת לאמר רמז כי לא דבר לו ה' לאמר להם, ואשר על כן הדבר בבל תאמר כמאמרם ז''ל (יומא ד':) וכתבנוהו בפסוק (י''א) וידבר וגו' שמעתי וגו', וזה הוא טעמו שלא הודיעם קודם. והעד הנאמן לדברי משה ה' מעידו בנוסח הנבואה כשאמר לו (פסוק ה') והיה ביום הששי וגו' תמצא שלא אמר לו ה' שם דבר אל בני ישראל ולא תיבת לאמר, הרי סתם הדבר בפניו שאין לו שליחות במצוה זו לישראל, והוא שאמר הוא אחר מעשה שלקטו לחם משנה ובאו לפניו גילה להם הדבר ואמר להם שלא היה אצלו אלא בדרך סוד נמסרו לו הדברים ולא לאומרם:
@86 **ויש** לנו לתת לב כפי זה מי התיר לו לאמר להם כל מצות האמורות בדבריו שלא נאמר לו דבר ולא לאמר:
@86 **ונראה** כי נתחכם משה בחקירת חכם למה לא רצה ה' שיאמר הדברים לישראל, והשכיל כי טעמו הוא שחפץ ה' לנטוע בהם נטע אמונת והצדקת מצות שבת שתהיה קבלתה וידיעתה ממנו אל עליון שלא על ידי שליח תחילה אלא כשיצאו ללקוט כמנהגם שיעור הרגיל ליומו וימודו וימצאו פי שנים מהרגיל יום יום יראו ראייה חושיית ושכליית כי ה' מצווה להם לבל יטרחו ביום שבת ומזמין להם מיום ששי צורך יום ז' כדי שבזה תהיה מצוה זו אצלם מקובלת בתום' קבלת הרצון ומורא גדול מעבור עליה לצד שמעלתה גדולה, וכמאמרם ז''ל (שמות דבה פכ''ה) שקול שבת כנגד כל התורה כולה, ולזה לא צוה להם תחלה על השבת משה כדי שלא יכוונו להרבות בלקיטה וילקטו כמשפט יום יום ויעשה להם הנס למצוא בכפלים אין זה אלא מעשה אלהים אשר ישיחם לשמור שבת. ואם תאמר סוף כל סוף יצוה להם משה על השבת ויאמר להם כי לא ילקטו אלא כשיעור זה הרגיל כדי להכיר הדבר, אין זה מהמוסר להבינם כי צריכין נם להצדיק דברי משה, לזה עשה ה' דבר חכמה:
@86 **ועוד** אם היה מקדים המצות על ידי משה עדיין יש מקום לטעות, על דרך מה שאמרו במנחות פרק רבי ישמעאל (ס''ה,) כשנטפל רבן יוחנן בן זכאי לבייתוסין הארורים ואמר להם עצרת אחר השבת מנין לכם ופטפט כנגדו זקן א' מהם ואמר לו משה אוהב ישראל היה ויודע עצרת יום אחד הוא עמד ותקנה אחר השבת כדי שיהיו מתענגין ב' ימים עד כאן. וכתבו התוספ' שם וזה לשונם עמד ותקנה והקב''ה הסכים על ידו עד כאן. הרי כי יש טועים שהגם שתהיה המצוה מפי משה יסכים הקב''ה על ידו, אם כן יש הפרש להקדמת ידיעת המצוה מנסיון אל עליון, לזה לא צוה ה' למשה לאמר לישראל דבר זה, ומעתה אחר שיצתה המחשבה אשר חשב אלהים והכירו ישראל הדבר תחלה אמר להם משה **הוא אשר דבר ה' אלי שבתון שבת קודש**. ואם תאמר למה לא הועיל ההיכר להשיג בו ידיעת שבת והוצרך משה לומר להם הדברים. הנה זולת דברי משה יטעו ויאמרו אולי נגמרה ירידת המן ולזה נתן להם ה' שלא כסדר הרגיל, לזה אמר להם משה **הוא אשר דבר** וגו' ולא לסיבה אחרת, ויוכר הדבר להם בהחלט כשירד המן יום א' אחר השבת. והוכרח משה לומר להם הדברים שהם בבל תאמר שלא יכשלו באותו שבת ויצאו אלא שלא אמר להם האזהרה בפירוש כאשר אבאר בפסוק עד אנה מאנתם:
@89 **אכלהו היום וגו'**. צריך לדעת למה הוצרך לצוותם על אכילתו. ואולי כי להיות שלא אמר להם אלא הניחו אותו למשמרת ולא פירש להם שיהיו מותרים באכילתו, והגם שלא מצינו שאסר בפירוש אכילת הנותר מכאן אתה למד שאסרו להם. או אולי דאסור מדין לא תאכל כל תועבה ואמרו ז''ל (חולין קי''ד:) כל שתעבתי לך הוא בבל תאכל, לזה אמר להם **אכלוהו היום**. ודקדק לומר **היום** לשלול יום אחר אסור הנותר לבקר, וכדי שלא תטעה ותאמר היום דוקא ולא יום אחר כל עיקר ואפילו שבת, לזה גמר אומר **כי שבת** וגו' הא למדת כי מיעוט היום לא בא למעט אלא שאינם שבת:
@89 **עוד** נתכוין באומרו **כי שבת** טעם למה שלאחריה על זה הדרך ולטעם שהיום שבת לא תמצאוהו בשדה, דקדק לומר **בשדה** לרמוז מאמר רבי שמעון בן יוחאי שאמר בזוהר (חלק ב' פח.) כי ביום שבת ירד המזון של כל ששת ימים למעלה ומאותו מזון יורד דבר יום ביומו, והוא אומרו **לא תמצאוהו בשדה** אבל למעלה בו ימצא אדרבה מזון לכל ו' ימים:
@90 **ששת ימים וגו'**. הכוונה בזה להזהירם לבל יצאו ללקוט, ופירוש **לא יהיה בו** לא יהיה בו מעשה זה של הלקיטה, שאם על הויית המן כבר אמר לא תמצאהו בשדה, ולזה כשיצאו מן העם ללקוט אמר ה' להם עד אנה מאנתם לשמור מצותי וגו' הרי שעברו על הלאו והיכן מצינו אזהרה זו שאמר להם כן, ואם כוונתו על דיוק הנשמע מאומרו ששת ימים לבד, לאו זה לא יקרא לאו אלא עשה כדין לאו הבא מכלל עשה (פסחים מא.) ולא יוצדק לומר להם עליו מאנתם לשמור כי לשון שמירה יאמר על הלאו:
@91 **ולא מצאו**. פירוש שאם מצאו היו לוקטין:
@92 **עד אנה מאנתם**. לפי מה שהעליתי בפסוק ויגידו למשה כי משה לא פעל און במה שלא אמר להם קודם ענין זה אם כן מה מקום לכוללו עם הממאנים לשמור מצות ה' ורבותינו ז''ל (בבא קמא צ''ב.) אמרו דבהדי הוצא לקי כרבא, ודבריהם ז''ל יצדיקו כי לא פעל מכשול. ולי נראה כי על כל פנים לא יכללנו הכתוב עם השאר אם לא היה לה' עליו חוט השערה מההקפדה. והצצתי במאמר משה בסמוך לפסוק זה שאמר לישראל ראו וגו' וצריך לדעת נבואה זו אימתי נאמרה למשה, אם נאמרה אחר שאמר לו עד אנה מאנתם קושיא לאלהינו למה לא צוה לו קודם לצוות ישראל אל יצא איש וגו', ואם נאמרה לו קודם איך לא אמרה משה לישראל:
@92 **אכן** זו היא שגיונו של איש האלהים כי ההתחכמות שנתחכם בהשכלתו בדברי ה' בטעם שלא אמר לו דבר וגו' או לאמר היה צריך לאומרה לישראל, והוא לא אמר להם אלא הוא אשר דבר ה' וגו' ולא אמר להם היוצא ממעשה זה אשר עשה ה' לחם משנה שהוא לתת להם השבת בדרך זה ממנו להם על דרך שפירשנו בפסוק (כ''ב) ויבואו כל נשיאי העדה וגו', והנה מזה יצא להם שיצאו ביום שבת קודש מן העם ללקוט כי חשבו כיון שלא אמר להם אזהרה בפירוש אלא דמפרש להם הענין הוא אשר דבר וגו' לא עשו הרגשה ויצאו ללקוט ולא חששו לזה עד אחר כך כשאמר להם אל יצא וגו' אז אמר הכתוב וישבתו העם וגו' הא למדת כי לא כן מקודם, אשר על כן כללו ה' ואמר עד אנה מאנתם. ולזה כשראה משה שהקפיד ה' עליו הבין הדברים ותכף אמר ראו כי ה' וגו', והם הדברים שנאמרו לו בתחילת דבר ה' בענין זה (פסוק ה') והכינו את אשר יביאו וכמו שפירשתי שם. והנה מכאן אתה למד שעל עיכוב מאמר זה לישראל כללו ה' עם הממאנים שהיה לו לומר לישראל כונת ה' כמו שהשיג לדעת הוא וכמו שפירשנו בפסוק ויגידו למשה. וסובר אני כי אין בדבר זה כדי להתיסר בשבט מוסר גדול עליו ליאמר לו עד אנה מאנתם כי הוא לא נצטווה וכחד ולא עבר אפילו על חוט השערה אלא שהיה לו להודיע לישראל מה שהשיג בדעת עליון כדי שלא ישגו לצאת כמו ששגגו ואין בזה עונש, לזה אמרו ז''ל בהדי הוצא לקי כרבא ליקוי שאינו ראוי לו:
@92 **מצותי ותורתי**. כי מצינו להם שעברו על ב' מצות, א' שאמר להם אל יותר ממנו והותירו, וב' שאמר להם תלקטוהו וביום השביעי לא יהיה בו הלקיטה ועברו ויצאו ללקוט לזה אמר עד אנה מאנתם לשמור מצותי, ואומרו **ותורותי** גם כן הם ב' תורות, א' כי ה' אמר להם שילקטו עומר לגלגולת והם לקטו יותר, וכמו שדרשו ז''ל (מכילתא) באומרו ולא העדיף המרבה, ובמעשה שבת גם כן לא הספיק להם מה שנתן להם משנה יום ששי ויצאו ללקוט יותר מעומר לגלגולת, וב' שלא האמינו במאמר ה' כי ביום שבת לא יהיה בו ויצאו וגו' ואין לך עובר על תורה כזה שאינו מאמין בתורת משה עבדו:
@93 **ראו כי ה' וגו'**. פירשתי למעלה שנתכוין משה לומר להם כי מצוה זו אינו צריך לאומרה הוא להם אלא הנה הם רואים אותה כי ה' נותן המצוה ממנו להם בלא שום אמצעי כמו שפירשתי בפסוק (כ''ב) ויגידו וגו' וזה למעלת השבת כי יראו ישראל הדכר בחוש הראות. ואומרו **אל יצא איש** פירוש כי ה' לא הוריד המן לצד שלא יצטרכו לצאת איש ממקומו וגו', ועיין מה שכתבתי בפסוק (כ''ח) עד אנה מאנתם:
@96 **ויאמר משה זה וגו'**. צריך לדעת אומרו **הדבר**. עוד צריך לדעת מצוה זו למי מצוה אותה משה, אם לאהרן הרי הוא אומר אחר כך ויאמר משה וגו'. ועוד כפל הדברים רואני כאן. ונראה כי כונת משה הוא על זה הדרך **זה הדבר אשר צוה** וגו' **מלא העומר** וגו' ולא אמר ה' מי יקחנו וגם לא אמר סדר לקיחתו, גם לא אמר מקום הנחתו אלא זה הוא הדיבור שיצא מפי ה' אלי ולא יותר, ויאמר אל אהרן שפט בצדק דעת חכם, כי פירוש למשמרת סובלת ב' דרכים, ומדרכי התורה כל שהתיבה תסבול ב' דברים שקולים במשמעותה תכוין אל הב' כי איזה מהם תוציא, וב' הדרכים הם, הא' למשמרת מן הטומאה, והב' מן שליחות יד. כנגד שליחות יד אמר מקום המשתמר באוהל מועד, גם שם מקום שצורכי ישראל נתונים שם התורה וכלי שרת וזה גם כן כלי שמשמש הוראת דבר אשר חפץ ה' להראות לדורות, וכמו כן עשה ה' במטה אהרן ובמחתות עדת קרח, ולזה אמר להניחו לפני ה', וכנגד שמירת טומאה אמר צנצנת אחת, ואמרו ז''ל (מכילתא) צנצנת דבר שהוא מציץ מחבירו שהוא כלי חרס שכל שצמיד פתיל עליו טהור, וב' פרטים אלו שמעם מדבר ה' באומרו למשמרת, ומעתה דן כי אהרן הוא הלוקח כי הוא הכהן המשרת במקדש ולזה ויאמר אל אהרן, ולבל יחשבו העם כי ה' אמר אליו לדבר אל אהרן ולקחת צנצנת וגו' לזה אמר הנאמן הגדול זה הדבר אשר צוה ה' ולא יותר, והחכם הבין הכוונה:
@96 **או** ירצה כי מתחילה כשקבל הנבואה סדרה לפני ישראל כסדר שמיעתה מאל עליון והיה חסר הידיעה מי העושה ומקום הנחת המן ומקום הנחת הכלי ולא ידע מה לעשות עד שבאה הנבואה פעם ב' ואמר לו ספקותיו, והוא אומרו בסוף המעשה **כאשר צוה ה' אל משה** פירוש לא תחשוב בדעתך כי פרטים שאינם מפורשים בדבר ה' שהם ג' הנזכרים משה מעצמו עשאן לא כן הוא אלא כאשר צוה ה' אל משה מפי עליון היו הדברים. ולדרך הראשון יתבאר אומרו **כאשר צוה ה'** וגו', יכוין הכתוב לומר כי הצדיקו עיונו של משה כאלו כן צוה ה' אליו כאשר שפט בדברים הסתומים כמו שפירשנו:
@96 **למשמרת לדורותיכם**. אמר לשון רבים, אחת היתה בדורו של ירמיה, ואחת תהיה לעתיד לבא כמאמרם ז''ל (מכילתא, כ''א תנחומא ג') שלשה דברים עתיד אליהו להעמיד לישראל ואחד מהם היא צלוחית של מן:
@99 **את המן אכלו וגו'**. הוצרך לומר פעם ב' את המן ולא סמך על הזכרתו בסמוך, להיות שיש שינוי בין אכילת המן שאכלו עד בואם אל ארץ נושבת למן שאכלו עד בואם לקצה ארץ כנען שהוא קודם העברת הירדן כי אותו שעד ארץ נושבת היה מהמן שבכלים לא שהיה יורד יום יום, לזה כשרצה להזכיר המן שאכלו עד בואם אל ארץ כנען זכר אותו בפני עצמו לומר כי ישתנה זה מזה, והשכל יכיר זה כי כל שיוסיף להתרחק זמן שהיה קרוב למקור שנתהוה ממנו יגשם יותר. עוד אמרו ז''ל (קידושין ל''ח.) וכי מ' שנה אכלו והלא חסרים ל' יום מט''ו בניסן עד ט''ז באייר אלא שהיו טועמים בעוגות טעם כמן. וראיתי לדקדק הכתוב למה שינה לשונו בתחילה כתיב **אכלו את המן** הקדים זכרון האכילה לזכרון המן, וכשהזכיר המן פעם ב' אמר **את המן אכלו** הקדים זכרון המן לזכרון האכילה. הנה הכתוב ידקדק לשונו לומר כי ישתנה חשבון מ' שנה שמנה באכילת המן למה שמודיעך שאכלו המן עד בואם וגו' מלבד ההפרש שכתבנו של ירידתו יום יום או מהשמור, כי המן שנכנס בחשבון מ' שנה אינו אלא בערך מה שהיו טועמים באכילתן, והוא שהקדים זכרון אכילה קודם זכרון המן לומר כי לצד האכילה הוכר היותו מן שהיו טועמים בעוגותיהם מן אבל אין כל המ' שנה מן ממש שהרי ל' יום אכלו מה שהוציאו ממצרים עוגות, וכשרצה להגביל שיעור זמן אכילת המן הקדים זכרונו לומר אין זה נחשב מן לצד שטעמו כן אלא לפי מה שהוא כפי האמת ודו''ק:
@101 **ויחנו ברפידים ואין מים**. לדבריהם ז''ל (בכורות ה:) אין רפידים אלא רפיון ידים מן התורה יכוין הכתוב לומר כשרפו ידיהם מן התורה שנמשלה למים לזה גם ה' מנע מהם המים מדה כנגד מדה:
@102 **וירב העם וגו'**. פירוש והמריבה הוא שאמרו להם בדרך זה תנו לנו מים וכי משה יש לו מים לתת להם אין זה אלא מריבה שאם היתה כוונתם לשאול כי יצעק אל ה' היה להם לומר כדרך שדברו אליו (חקת כא ז) כששלח ה' בהם נחשים שרפים. או אפשר שהיו תובעים המים כמי שתובע חוב מחברו ואומר לו תן לי מה שאתה חייב לי, ואמרו לשון רבים ודבריהם עם משה לבד, כאן כללו לה'. ולזה אמר להם משה **מה תריבון עמדי מה תנסון את ה'**. ואמר בסדר זה כי בערך ה' כבר ידעו כי כל יכול אלא מנסים אם יש בקרבם:
@103 **ויצמא שם וגו'**. הנה הענין יוליד התימה למה יביאם ה' אל הנסיון הגדול הזה למות בצמא, וכפי השכל ישער אדם שדבר זה וכדומה תוליד הכפירה. ועוד תגדל הקושיא על משה שבמקום שיאזור חלציו בתפלה ובתחנונים בא בטענה לפני ה' עוד מעט וגו' שיראה כי לא חשש על צמאונם ועל מות בני ישראל בצמא כי הכתוב מעיד כי צמאו למים:
@103 **ונראה** כי ה' ניסה אותם להדריכם לשאת עיניהם ולהתפלל לפני ה' כי זה עיקר גדול באמונה ובהשלמת הנפש. ותמצא שנתחכם ה' על הדבר ולא נתן להם מן יום לחודש אלא דבר יום ביומו, ואשר על כן מנע מהם הנם עד שיתחננו למול קונם וישמע צעקתם, ומודיע הכתוב כי במקום שיצעקו לה' היו מריבין עם משה וכשתקף עליהם הצמאון וילן העם על משה, לזה סדר הכתוב סדר המעשה ויצמא וגו' וילן וגו', לומר שלא עשו דבר זולת זה הא למדת כי לא צעקו לה'. וכן העיד הכתוב על נסותם וגו' היש ה' בקרבנו אם אין הא למדת כי לא היו מצדיקים בההשגחה. והן האדון ברוך הוא היה מכריחם לצעוק אליו ולהסיר המחשבה הרעה באמצעות תוקף הצמאון, וכל זה השכיל והבין משה ולזה לא התפלל אל ה' והיה מצפה לתקות האדון מהם, וכשראה כי גדול הכאב אמר לפני ה' **מה אעשה לעם הזה** פירוש מה אעשה להם להרחיק תלונתם מעלי ומזה תדע כי הרגיש משה כי אין דבר זה תלוי בתפלה שאם לא כן היה מתפלל כמו שעשה על הים, ולו יהיה שלא נענה היה מוסיף בתפלה עד שיענהו ה', וטען עוד לפני ה' **עוד מעט** וגו' פירוש אם תוסיף לצערם עוד מעט תולדות הדבר שתצא מהם היא וסקלוני, ולו יהיה שאחר תוסיף לצערם עד שיצעקו לפניך בבכיה רבה ותצא כוונת ה' לפועל אבל ביני ביני וילך משה בסקילה, וזו טענה הנשמעת. וראיתי לתת לב איך עם ה' הרואים דברים המופלאים והנוראים במצרים ועל הים ובמדבר יטעו בדבר ולא יצעקו אל ה' והלא הם המכירים תועלת הצעקה כי שמע את נאקתם במצרים. ואולי כי דעתם היה שאין צורך לתפילה על הדבר כל שה' ישנו בתוכם, כי אחר שהביאם למדבר פשיטא שלא הביאם אלא לספק צורכם שאם לא כן הלא המה אבודים ולא יצטרכו לתפלה ואין זה אלא שאין ה' בקרבם, והוא הנסיון שאמרו היש ה' בקרבנו וגו':
@105 **עבור לפני העם וגו'**. אולי שידע ה' כי גדל הצמאון בעם ויהיו מסתכנים אפילו בזמן מועט, לזה אמר כי מדי עוברו יעבור לפני העם פירוש בדרך שידעו שאתה הולך למצוא להם מים כדי שישקוט אש הצמאון מהם ביני וביני ולא תעבור דרך שלא יהיה לפניהם, וגם קח עמך הזקנים כדי שתהיה ההרגשה:
@105 **אשר הכית בו וגו'**. וזה יהיה לנס עצום כי זה אשר הבאיש המים הנמצאים ועשאם דם יפעול בכח עליון פעולה נגדיית שימציא מים לשתות העם. ויש בזה הכחשות מופלאות מנגדות למתחכמים להכחיש כי הם פלאות אלהי ישראל במטה זה תבקע קרקפתו החושבת זרות:
@106 **הנני עומד וגו'**. פירוש לפניך במקום זה ושם על הצור, כי מלא כל הארץ כבודו בתמידות באין השתנות מקום שלא יהיה בו שוכן השוכן אלא יש מקום שתגדל בו השראת שכינתו יתברך, או כפי מעלת הכנת המקום כמקום המקודש, או כפי השרויים בתוכו:
@108 **ויבא עמלק וגו'**. להיות שנתעצלו בתורה שנמשלה למים ולאש דכתיב (ירמי' כ''ג) כה דברי כאש ולא נתעסקו במלחמתה של תורה, לזה הענישם בצמאון כנגד בחינת המים ובאש המלחמה של עמלק:
@109 **ויאמר משה אל יהושע**. נתחכם משה כשהכיר העון שהוא לצד ביטול מלחמת התורה אמר אין ראוי לצאת למלחמה אלא יהושע שנאמר עליו (לקמן ל''ג י''א) לא ימיש מתוך האוהל בעסק התורה, ואמר לו שיבחר כיוצא בו ובזה יתגבר עליו וכן היה:
@114 **ושים באזני וגו'**. צריך לדעת למה נתיחד מאמר זה ליהושע לבד. ואולי כי לצד שראה יהושע עוצם הכעסת עמלק ותוקפו ולא היה בו כח לעשות בו כליון אלא שהחלישם לבד ויש בלבו של צדיק איך לא עשה ה' מה שראוי לעשות ברשע זה, לזה בא ה' להפיג צנתו וצוה למשה לאמר לו באזנו פירוש כי הדבר הוא להשיב למה שבלבו של יהושע ואמר לו כי לא ידאג על הדבר מחה אמחה וגו' ודבר ה' כאילו כבר היה ותהיה זאת נחמתו. וטעם כפל מחה וגו' אולי שרמז לנו זמנים שימחה בהם, א' בימי שאול וכנגדו אמר מחה, ב' בימי מרדכי וכנגדו אמר אמחה, ואחת לעתיד וכנגדו אמר מתחת השמים:
@114 **חסלת פרשת בשלח**
